INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4885c34a-c053-5cb0-b1a9-b6c91a9ca43a', '6c47e830-a004-5fbb-99a1-ba45df4ea52d', '{"en": "Which of these breaks wudu?", "bn": "কোনটি অজু ভঙ্গ করে?"}', '{"en": "The Prophet ﷺ said prayer is not accepted from one who broke wudu until he makes wudu again; passing wind breaks it.", "bn": "নবী ﷺ বলেছেন, অজু ভেঙে গেলে নতুন অজু ছাড়া নামাজ কবুল হয় না; বায়ু নির্গত হলে অজু ভাঙে।"}', 'Sahih al-Bukhari 135', 1) ON CONFLICT (id) DO NOTHING;
