INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6fb0747d-6ec5-5d54-bc7c-017aeb8209e6', '6c47e830-a004-5fbb-99a1-ba45df4ea52d', '{"en": "Purifying with clean earth when there is no water is called…?", "bn": "পানি না থাকলে পবিত্র মাটি দিয়ে পবিত্রতা অর্জনকে কী বলে?"}', '{"en": "\"…and you find no water, then do tayammum with clean earth.\"", "bn": "\"…আর পানি না পাও, তবে পবিত্র মাটি দিয়ে তায়াম্মুম করো।\""}', 'Quran 4:43', 2) ON CONFLICT (id) DO NOTHING;
