INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('2fae5e40-e203-5e95-9786-d021736f2ece', '34e01e92-7c25-540d-9448-1e8f62943485', '{"en": "Who was the mu’adhdhin of the Prophet ﷺ?", "bn": "নবীজির ﷺ মুয়াজ্জিন কে ছিলেন?"}', '{"en": "Bilal, who endured torture in Makkah saying \"Ahad, Ahad\".", "bn": "বিলাল (রা.), মক্কায় নির্যাতন সয়েও যিনি বলতেন \"আহাদ, আহাদ\"।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
