INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ee8729a1-4b8b-5c30-bd93-f69043755894', '34e01e92-7c25-540d-9448-1e8f62943485', '{"en": "Who was called \"the Sword of Allah\"?", "bn": "কাকে \"আল্লাহর তরবারি\" বলা হয়?"}', '{"en": "The Prophet ﷺ called Khalid \"a sword from the swords of Allah\".", "bn": "নবী ﷺ খালিদকে \"আল্লাহর তরবারিসমূহের একটি\" বলেছেন।"}', 'Sahih al-Bukhari 3757', 5) ON CONFLICT (id) DO NOTHING;
