INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d50c6816-56d5-53cb-92bf-3a900afaa5d6', '34e01e92-7c25-540d-9448-1e8f62943485', '{"en": "Who was called \"the trustworthy one of this ummah\"?", "bn": "কাকে \"এই উম্মতের আমিন (বিশ্বস্ত)\" বলা হয়েছে?"}', '{"en": "\"Every nation has a trustworthy one, and ours is Abu ‘Ubaydah.\"", "bn": "\"প্রত্যেক উম্মতের একজন আমিন আছে, আমাদের আমিন আবু উবাইদা।\""}', 'Sahih al-Bukhari 3744', 7) ON CONFLICT (id) DO NOTHING;
