INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('80558c27-1d33-5842-8a43-9dfa45855880', 'b1a2a778-e5cb-5e96-8a84-41b67ba12dba', '{"en": "Which woman is named in the Quran?", "bn": "কোন নারীর নাম কুরআনে আছে?"}', '{"en": "Maryam is the only woman named in the Quran; a surah is named after her.", "bn": "মারইয়াম (আ.) কুরআনে নাম উল্লেখিত একমাত্র নারী; তাঁর নামে একটি সূরা আছে।"}', 'Quran 19', 3) ON CONFLICT (id) DO NOTHING;
