INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('03262566-c220-5c30-a710-82b00fa6ad47', 'f371ac12-10bc-5740-95f5-46dde45cdfff', '{"en": "Which prophet understood the speech of an ant?", "bn": "কোন নবী পিঁপড়ার কথা বুঝতেন?"}', '{"en": "\"So he smiled, amused at her speech.\"", "bn": "\"অতঃপর তিনি তার কথায় মুচকি হাসলেন।\""}', 'Quran 27:18–19', 2) ON CONFLICT (id) DO NOTHING;
