INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9043eee0-dd71-57ce-af9a-913ee394103b', 'b90a93e5-faad-5cd9-9e6d-412ebea73dca', '{"en": "Which surah is equal to a third of the Quran?", "bn": "কোন সূরা কুরআনের এক-তৃতীয়াংশের সমান?"}', '{"en": "\"By Him in whose hand my soul is, it equals a third of the Quran.\"", "bn": "\"যাঁর হাতে আমার প্রাণ, তাঁর কসম, এটি কুরআনের এক-তৃতীয়াংশের সমান।\""}', 'Sahih al-Bukhari 5013', 3) ON CONFLICT (id) DO NOTHING;
