INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ca4de717-d388-5c3c-9a59-29885bd4922a', '291a98bb-29b8-5e2a-b8c3-94a408d4f06b', '{"en": "Whose staff turned into a snake?", "bn": "কার লাঠি সাপে পরিণত হয়েছিল?"}', '{"en": "\"So he threw it, and at once it was a snake, moving swiftly.\"", "bn": "\"অতঃপর তিনি তা নিক্ষেপ করলেন, আর তা হয়ে গেল ছুটন্ত সাপ।\""}', 'Quran 20:20', 4) ON CONFLICT (id) DO NOTHING;
