INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4f4abc47-2fb0-5063-8563-36df97baa5db', '291a98bb-29b8-5e2a-b8c3-94a408d4f06b', '{"en": "Which prophet healed the blind and the leper by Allah’s permission?", "bn": "কোন নবী আল্লাহর অনুমতিতে অন্ধ ও কুষ্ঠরোগীকে সুস্থ করতেন?"}', '{"en": "\"…and I heal the blind and the leper, and give life to the dead, by permission of Allah.\"", "bn": "\"…আর আমি আল্লাহর অনুমতিতে অন্ধ ও কুষ্ঠরোগীকে সুস্থ করি এবং মৃতকে জীবিত করি।\""}', 'Quran 3:49', 5) ON CONFLICT (id) DO NOTHING;
