INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d3287a5f-7ccc-5f01-b7de-8270324cae31', '291a98bb-29b8-5e2a-b8c3-94a408d4f06b', '{"en": "Who was called \"Khalilullah\", the close friend of Allah?", "bn": "কাকে \"খলিলুল্লাহ\" (আল্লাহর অন্তরঙ্গ বন্ধু) বলা হয়?"}', '{"en": "\"And Allah took Ibrahim as an intimate friend.\"", "bn": "\"আর আল্লাহ ইবরাহিমকে অন্তরঙ্গ বন্ধু হিসেবে গ্রহণ করেছেন।\""}', 'Quran 4:125', 10) ON CONFLICT (id) DO NOTHING;
