INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('df2f5c87-584d-5276-b8c3-1ba0dfbdd1e6', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "How many groups may receive zakat?", "bn": "কত শ্রেণির মানুষ যাকাত পেতে পারে?"}', '{"en": "The poor, the needy, its collectors, those whose hearts are reconciled, freeing captives, debtors, in the way of Allah, and the stranded traveller.", "bn": "গরিব, মিসকিন, আদায়কারী, মন জয় করার জন্য, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে এবং বিপদগ্রস্ত মুসাফির।"}', 'Quran 9:60', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3b2f9053-bc29-5a12-9ac6-3b177b0f6d55', 'df2f5c87-584d-5276-b8c3-1ba0dfbdd1e6', '{"en": "4", "bn": "৪"}', false, 1), ('470b7dd3-dff2-534c-8abf-a1c5914cf4bb', 'df2f5c87-584d-5276-b8c3-1ba0dfbdd1e6', '{"en": "6", "bn": "৬"}', false, 2), ('167ec357-af85-5b7d-9084-5663805b74ac', 'df2f5c87-584d-5276-b8c3-1ba0dfbdd1e6', '{"en": "8", "bn": "৮"}', true, 3), ('c576cc6e-b644-5215-aa56-a58cb28a565e', 'df2f5c87-584d-5276-b8c3-1ba0dfbdd1e6', '{"en": "10", "bn": "১০"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9318c138-a9e5-589d-915c-68e78bf4fe10', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Voluntary charity is called…?", "bn": "নফল দানকে কী বলে?"}', '{"en": "Sadaqah: any charity given for Allah’s sake.", "bn": "সদকা: আল্লাহর সন্তুষ্টির জন্য যেকোনো দান।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('32f23860-4f54-5faf-a865-a2a56e05c0ad', '9318c138-a9e5-589d-915c-68e78bf4fe10', '{"en": "Sadaqah", "bn": "সদকা"}', true, 1), ('50699e70-a98c-5477-8016-d120b2fa8b01', '9318c138-a9e5-589d-915c-68e78bf4fe10', '{"en": "Jizyah", "bn": "জিজিয়া"}', false, 2), ('c3b7e4bb-5853-550e-900d-143f4a459c31', '9318c138-a9e5-589d-915c-68e78bf4fe10', '{"en": "Kharaj", "bn": "খারাজ"}', false, 3), ('6e6f171d-997b-5f12-8c56-7c48cdfa63ef', '9318c138-a9e5-589d-915c-68e78bf4fe10', '{"en": "Diyah", "bn": "দিয়াত"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b9c24da6-d3b5-5619-8834-5d6489a9da47', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Charity that keeps rewarding after death is called…?", "bn": "মৃত্যুর পরেও সওয়াব দিতে থাকা দানকে কী বলে?"}', '{"en": "\"When a person dies, his deeds end except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.\"", "bn": "\"মানুষ মারা গেলে তার আমল বন্ধ হয়, তিনটি ছাড়া: চলমান সদকা, উপকারী জ্ঞান, অথবা নেক সন্তান যে তার জন্য দোয়া করে।\""}', 'Sahih Muslim 1631', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d6470bda-c236-5962-9e90-e32837e45c29', 'b9c24da6-d3b5-5619-8834-5d6489a9da47', '{"en": "Sadaqah jariyah", "bn": "সদকায়ে জারিয়া"}', true, 1), ('d6285659-7ab2-5daf-81b2-0451947c8e33', 'b9c24da6-d3b5-5619-8834-5d6489a9da47', '{"en": "Fidyah", "bn": "ফিদিয়া"}', false, 2), ('aa931ecb-f9e0-5a71-bbcc-1315ed098017', 'b9c24da6-d3b5-5619-8834-5d6489a9da47', '{"en": "Kaffarah", "bn": "কাফফারা"}', false, 3), ('0ee17f8a-3697-58ca-a425-7606f930395f', 'b9c24da6-d3b5-5619-8834-5d6489a9da47', '{"en": "Mahr", "bn": "মোহর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('03c42e08-ce84-5a5c-b7ef-937f8324d13c', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Zakat on savings is due after they stay above the nisab for…?", "bn": "সঞ্চয় কতদিন নিসাবের ওপরে থাকলে যাকাত ফরজ হয়?"}', '{"en": "A full lunar year (hawl).", "bn": "পূর্ণ এক চান্দ্র বছর (হাওল)।"}', 'Sunan Abi Dawud 1573', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f1052424-f4cb-5113-9b44-8a0edf15856d', '03c42e08-ce84-5a5c-b7ef-937f8324d13c', '{"en": "One week", "bn": "এক সপ্তাহ"}', false, 1), ('a357a534-2ae9-5e1e-a61c-4aae601cc7e9', '03c42e08-ce84-5a5c-b7ef-937f8324d13c', '{"en": "One month", "bn": "এক মাস"}', false, 2), ('fd4e75cd-9e91-5c3b-8499-861af450dde4', '03c42e08-ce84-5a5c-b7ef-937f8324d13c', '{"en": "One lunar year", "bn": "এক চান্দ্র বছর"}', true, 3), ('e9032a44-f682-58c8-9386-5d86e2ca748f', '03c42e08-ce84-5a5c-b7ef-937f8324d13c', '{"en": "Ten years", "bn": "দশ বছর"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('68faf870-65ff-502d-aabb-7d7c949d1ebc', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Among those shaded on the Day of Judgement is one who gave charity so secretly that…?", "bn": "কিয়ামতের দিন ছায়াপ্রাপ্তদের একজন এমনভাবে গোপনে দান করেছে যে…?"}', '{"en": "One of the seven whom Allah shades in His shade.", "bn": "আল্লাহ যে সাত শ্রেণিকে তাঁর ছায়ায় আশ্রয় দেবেন, তাদের একজন।"}', 'Sahih al-Bukhari 660', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('00194ddf-112a-5313-8654-d5b3aa2f1665', '68faf870-65ff-502d-aabb-7d7c949d1ebc', '{"en": "His left hand did not know what his right gave", "bn": "তার বাম হাত জানত না ডান হাত কী দিয়েছে"}', true, 1), ('4b10b64c-1b9a-556a-8e46-addcff4d2c52', '68faf870-65ff-502d-aabb-7d7c949d1ebc', '{"en": "Nobody received it", "bn": "কেউ তা পায়নি"}', false, 2), ('f5ada626-e92f-526e-be46-c3423838d5e3', '68faf870-65ff-502d-aabb-7d7c949d1ebc', '{"en": "He forgot it", "bn": "সে ভুলে গেছে"}', false, 3), ('3dc977a0-9144-57e7-8fee-f086b270ab00', '68faf870-65ff-502d-aabb-7d7c949d1ebc', '{"en": "It was in the masjid", "bn": "তা মসজিদে ছিল"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('dcae67c3-eeda-5696-8a49-deb54db1fa86', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "According to the hadith, what does charity do to wealth?", "bn": "হাদিস অনুযায়ী দান সম্পদের কী করে?"}', '{"en": "\"Charity does not decrease wealth.\"", "bn": "\"দান সম্পদ কমায় না।\""}', 'Sahih Muslim 2588', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9ed5f069-c4aa-580c-9b91-637cb149a584', 'dcae67c3-eeda-5696-8a49-deb54db1fa86', '{"en": "It does not decrease it", "bn": "তা কমায় না"}', true, 1), ('bb9e894a-3296-542e-a8ff-03123540c44a', 'dcae67c3-eeda-5696-8a49-deb54db1fa86', '{"en": "It halves it", "bn": "অর্ধেক করে"}', false, 2), ('0082c9c1-85c2-5793-b4dd-75d8c730b679', 'dcae67c3-eeda-5696-8a49-deb54db1fa86', '{"en": "It ends it", "bn": "শেষ করে দেয়"}', false, 3), ('ccf42eb1-c6c5-50cf-8467-298009110d45', 'dcae67c3-eeda-5696-8a49-deb54db1fa86', '{"en": "Nothing is said", "bn": "কিছু বলা হয়নি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0a11429e-1cc7-5e75-9267-2b2433ec3631', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "To whom may you NOT give your zakat?", "bn": "কাকে আপনার যাকাত দেওয়া যায় না?"}', '{"en": "You support your parents and children from your own wealth, not from zakat.", "bn": "বাবা-মা ও সন্তানের ভরণপোষণ নিজের সম্পদ থেকে দিতে হয়, যাকাত থেকে নয়।"}', NULL, 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c6f6a88b-5ead-5241-9491-a008316e3fb7', '0a11429e-1cc7-5e75-9267-2b2433ec3631', '{"en": "A poor neighbour", "bn": "গরিব প্রতিবেশী"}', false, 1), ('43436ed8-84a4-5753-9354-35bd67b80ff6', '0a11429e-1cc7-5e75-9267-2b2433ec3631', '{"en": "A stranded traveller", "bn": "বিপদগ্রস্ত মুসাফির"}', false, 2), ('473cf626-2e80-5d02-ac1e-9827b64d9be5', '0a11429e-1cc7-5e75-9267-2b2433ec3631', '{"en": "Your own parents", "bn": "নিজের বাবা-মা"}', true, 3), ('ee496232-a932-56de-a2b7-a438570671e3', '0a11429e-1cc7-5e75-9267-2b2433ec3631', '{"en": "A person in debt", "bn": "ঋণগ্রস্ত ব্যক্তি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('386a44ac-05c7-5598-a041-d920e7bf3282', '81aa5327-18cd-5fd1-aae9-12ee2288fceb', '{"en": "Which charity is best, according to the hadith?", "bn": "হাদিস অনুযায়ী কোন দান সর্বোত্তম?"}', '{"en": "\"…that you give while healthy, fearing poverty and hoping for wealth.\"", "bn": "\"…যা তুমি সুস্থ অবস্থায়, দারিদ্র্যের ভয় ও ধনী হওয়ার আশা নিয়ে দাও।\""}', 'Sahih al-Bukhari 1419', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('025f0b39-d820-5519-8830-8258de39d94a', '386a44ac-05c7-5598-a041-d920e7bf3282', '{"en": "Given while healthy and hoping to be rich", "bn": "সুস্থ অবস্থায়, ধনী হওয়ার আশা থাকতে দেওয়া দান"}', true, 1), ('c746f42a-91ee-55f8-9a7d-dcfe567e6808', '386a44ac-05c7-5598-a041-d920e7bf3282', '{"en": "Given only at death", "bn": "শুধু মৃত্যুর সময় দেওয়া"}', false, 2), ('7e120b14-f906-564a-b12e-3534877ca719', '386a44ac-05c7-5598-a041-d920e7bf3282', '{"en": "Given for praise", "bn": "প্রশংসার জন্য দেওয়া"}', false, 3), ('b4e60be4-f6f5-509a-88a4-2a21f467e77c', '386a44ac-05c7-5598-a041-d920e7bf3282', '{"en": "Given rarely", "bn": "কদাচিৎ দেওয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Holy places", "bn": "পবিত্র স্থানসমূহ"}', 'history', 'easy', NULL, 10, 'in_review', 21) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e1851fc8-70b6-5885-9350-4a7badf554bc', 'a08574d0-8533-5a3a-bac9-948e078d147b', '{"en": "Masjid al-Haram is in…?", "bn": "মসজিদুল হারাম কোথায়?"}', '{"en": "It surrounds the Ka‘bah.", "bn": "এটি কাবাকে ঘিরে আছে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
