INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "Islamic words we use", "bn": "আমাদের ব্যবহৃত ইসলামি শব্দ"}', 'general', 'easy', NULL, 10, 'in_review', 22) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('157dd877-48a6-5c7c-bdab-3ca66a37d1af', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"Insha’Allah\" mean?", "bn": "\"ইনশাআল্লাহ\" অর্থ কী?"}', '{"en": "\"And never say of anything, I will do it tomorrow, except (adding) if Allah wills.\"", "bn": "\"কোনো বিষয়ে বোলো না যে আমি আগামীকাল এটা করব, তবে আল্লাহ চাইলে (বলে)।\""}', 'Quran 18:23–24', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6c868c3c-d7bf-5b09-9c55-cb7aeb97a5d3', '157dd877-48a6-5c7c-bdab-3ca66a37d1af', '{"en": "If Allah wills", "bn": "আল্লাহ চাইলে"}', true, 1), ('2e6aa16b-8343-570e-9500-88a9bdbb8f94', '157dd877-48a6-5c7c-bdab-3ca66a37d1af', '{"en": "Thank you", "bn": "ধন্যবাদ"}', false, 2), ('ee818e6a-63a8-5045-b029-8478e69d4ead', '157dd877-48a6-5c7c-bdab-3ca66a37d1af', '{"en": "Goodbye", "bn": "বিদায়"}', false, 3), ('ce72b004-039e-5b10-8ff5-308fb7950598', '157dd877-48a6-5c7c-bdab-3ca66a37d1af', '{"en": "Well done", "bn": "বাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('93d0839b-37f2-5d1a-a910-45dc6a8e0309', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"Masha’Allah\" mean?", "bn": "\"মাশাআল্লাহ\" অর্থ কী?"}', '{"en": "Said when admiring something: \"What Allah willed; there is no power except with Allah.\"", "bn": "কিছু দেখে মুগ্ধ হলে: \"আল্লাহ যা চেয়েছেন; আল্লাহ ছাড়া কোনো শক্তি নেই।\""}', 'Quran 18:39', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('53383b88-6d22-57bd-b24a-33cd8d39d93b', '93d0839b-37f2-5d1a-a910-45dc6a8e0309', '{"en": "What Allah has willed", "bn": "আল্লাহ যা চেয়েছেন"}', true, 1), ('84aed74c-2e59-5259-9a51-9e0cd99530fa', '93d0839b-37f2-5d1a-a910-45dc6a8e0309', '{"en": "Sorry", "bn": "দুঃখিত"}', false, 2), ('66347851-904f-50ef-b1bb-23def6e405b9', '93d0839b-37f2-5d1a-a910-45dc6a8e0309', '{"en": "Hurry up", "bn": "তাড়াতাড়ি"}', false, 3), ('a4c59e34-2b9c-5487-b01b-6b1d0720d470', '93d0839b-37f2-5d1a-a910-45dc6a8e0309', '{"en": "Peace", "bn": "শান্তি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('fa07a5b9-e195-50a2-8fce-767e9f4f1274', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"SubhanAllah\" mean?", "bn": "\"সুবহানাল্লাহ\" অর্থ কী?"}', '{"en": "It declares Allah free of every imperfection.", "bn": "এটি ঘোষণা করে যে আল্লাহ সব ত্রুটি থেকে মুক্ত।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('6b8dc91f-f649-5993-94d3-c3cb64665ab6', 'fa07a5b9-e195-50a2-8fce-767e9f4f1274', '{"en": "Glory be to Allah", "bn": "আল্লাহ পবিত্র"}', true, 1), ('fa7dbc23-caea-51fa-b0b0-f3930c15937a', 'fa07a5b9-e195-50a2-8fce-767e9f4f1274', '{"en": "Allah is great", "bn": "আল্লাহ মহান"}', false, 2), ('ac26c19e-e427-5758-863e-6a07790caf39', 'fa07a5b9-e195-50a2-8fce-767e9f4f1274', '{"en": "Praise be to Allah", "bn": "সব প্রশংসা আল্লাহর"}', false, 3), ('f26b79b7-43e7-5811-9292-5b3e5b8701ea', 'fa07a5b9-e195-50a2-8fce-767e9f4f1274', '{"en": "I seek forgiveness", "bn": "ক্ষমা চাই"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c3caf135-20b5-5a5c-8453-c93ad3b57322', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"JazakAllahu khayran\" mean?", "bn": "\"জাযাকাল্লাহু খাইরান\" অর্থ কী?"}', '{"en": "\"Whoever is done a favour and says JazakAllahu khayran has praised well.\"", "bn": "\"যার উপকার করা হয় এবং সে বলে জাযাকাল্লাহু খাইরান, সে যথাযথ প্রশংসা করল।\""}', 'Jami‘ at-Tirmidhi 2035', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('871f8f8f-f63c-5699-9bff-8ba466272735', 'c3caf135-20b5-5a5c-8453-c93ad3b57322', '{"en": "May Allah reward you with good", "bn": "আল্লাহ আপনাকে উত্তম প্রতিদান দিন"}', true, 1), ('7e82ba5f-8eee-5d77-8bf9-67e24dd9f428', 'c3caf135-20b5-5a5c-8453-c93ad3b57322', '{"en": "Good night", "bn": "শুভ রাত্রি"}', false, 2), ('98095490-ad49-5f7f-b328-c3c51cdf7b7c', 'c3caf135-20b5-5a5c-8453-c93ad3b57322', '{"en": "Excuse me", "bn": "মাফ করবেন"}', false, 3), ('6b2790e0-f3d8-589b-b992-49e38e6f41e9', 'c3caf135-20b5-5a5c-8453-c93ad3b57322', '{"en": "Welcome", "bn": "স্বাগতম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('30f27d53-cc48-5e23-be29-3ccbfe73a00a', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"Astaghfirullah\" mean?", "bn": "\"আস্তাগফিরুল্লাহ\" অর্থ কী?"}', '{"en": "The Prophet ﷺ sought forgiveness more than seventy times a day.", "bn": "নবী ﷺ দিনে সত্তরবারের বেশি ইস্তিগফার করতেন।"}', 'Sahih al-Bukhari 6307', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('e781a4fa-75d6-5814-97c5-a55dfb9decbb', '30f27d53-cc48-5e23-be29-3ccbfe73a00a', '{"en": "I seek Allah’s forgiveness", "bn": "আমি আল্লাহর কাছে ক্ষমা চাই"}', true, 1), ('f9a1462e-b458-5649-9c94-a47e111c57f5', '30f27d53-cc48-5e23-be29-3ccbfe73a00a', '{"en": "I trust Allah", "bn": "আমি আল্লাহর ওপর ভরসা করি"}', false, 2), ('5e159cd3-e7a6-5328-9b22-de95fbc3b64b', '30f27d53-cc48-5e23-be29-3ccbfe73a00a', '{"en": "Allah is One", "bn": "আল্লাহ এক"}', false, 3), ('747f9932-86fa-50dd-a056-f45e457b9d4c', '30f27d53-cc48-5e23-be29-3ccbfe73a00a', '{"en": "Thank Allah", "bn": "আল্লাহর শুকরিয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('70cbac9c-5608-583b-9ff2-00c0a59de00d', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "When do we say \"Inna lillahi wa inna ilayhi raji‘un\"?", "bn": "\"ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন\" কখন বলি?"}', '{"en": "\"…who, when disaster strikes them, say: Indeed we belong to Allah and to Him we return.\"", "bn": "\"…যারা বিপদে পড়লে বলে: আমরা আল্লাহরই এবং তাঁর দিকেই ফিরে যাব।\""}', 'Quran 2:156', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2891df6f-0ec9-52f6-a006-a5955e29b9ab', '70cbac9c-5608-583b-9ff2-00c0a59de00d', '{"en": "When a calamity or death happens", "bn": "বিপদ বা মৃত্যুর সময়"}', true, 1), ('ddae6eaf-935a-5e0d-8522-3d6222380ac9', '70cbac9c-5608-583b-9ff2-00c0a59de00d', '{"en": "Before eating", "bn": "খাওয়ার আগে"}', false, 2), ('d6ea3d73-21c9-57b6-a736-1a21acf3d5b5', '70cbac9c-5608-583b-9ff2-00c0a59de00d', '{"en": "When sneezing", "bn": "হাঁচির সময়"}', false, 3), ('1604e215-1d84-59e3-8640-ee450cb71b78', '70cbac9c-5608-583b-9ff2-00c0a59de00d', '{"en": "When greeting", "bn": "সালামের সময়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6bde2e22-3fac-55e4-a586-9ee40245e15c', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"Allahu Akbar\" mean?", "bn": "\"আল্লাহু আকবার\" অর্থ কী?"}', '{"en": "Said in every salah and the adhan.", "bn": "প্রতি নামাজ ও আজানে বলা হয়।"}', NULL, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('08dc5dd9-8ebf-5048-bd74-3b68aae7e585', '6bde2e22-3fac-55e4-a586-9ee40245e15c', '{"en": "Allah is the Greatest", "bn": "আল্লাহ সর্বশ্রেষ্ঠ"}', true, 1), ('a4738f3a-2b06-5a96-8ae7-5953218c96ea', '6bde2e22-3fac-55e4-a586-9ee40245e15c', '{"en": "Allah is One", "bn": "আল্লাহ এক"}', false, 2), ('8a4b3575-7db5-5980-ac00-76af82b71547', '6bde2e22-3fac-55e4-a586-9ee40245e15c', '{"en": "Allah forgives", "bn": "আল্লাহ ক্ষমা করেন"}', false, 3), ('f24c0a5e-07f9-5517-a3c0-699451e66bd2', '6bde2e22-3fac-55e4-a586-9ee40245e15c', '{"en": "Allah knows", "bn": "আল্লাহ জানেন"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1715cf30-6fa1-56c8-bde9-64c08e2a3fcf', 'ce841ed7-e99d-539b-91bb-cfd63064604b', '{"en": "What does \"Ameen\" mean?", "bn": "\"আমিন\" অর্থ কী?"}', '{"en": "Said after al-Fatiha and after a dua.", "bn": "সূরা ফাতিহা ও দোয়ার পরে বলা হয়।"}', 'Sahih al-Bukhari 780', 8) ON CONFLICT (id) DO NOTHING;
