INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9d065ed1-d310-5f4a-9875-97b404551ad6', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "Which two phrases are light on the tongue and heavy on the Scale?", "bn": "কোন দুটি বাক্য জিহ্বায় হালকা আর মিজানে ভারী?"}', '{"en": "\"…beloved to the Most Merciful.\"", "bn": "\"…দয়াময়ের কাছে প্রিয়।\""}', 'Sahih al-Bukhari 6406', 2) ON CONFLICT (id) DO NOTHING;
