INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6f995717-7972-5f67-bab6-aa434d7e39a0', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "After the adhan, the Prophet ﷺ taught us to ask Allah to grant him…?", "bn": "আজানের পর নবী ﷺ আমাদের শিখিয়েছেন তাঁর জন্য আল্লাহর কাছে কী চাইতে?"}', '{"en": "\"…then ask Allah to grant me al-Wasilah, a rank in Paradise.\"", "bn": "\"…তারপর আমার জন্য আল্লাহর কাছে ওয়াসিলা চাও, যা জান্নাতের একটি মর্যাদা।\""}', 'Sahih Muslim 384', 5) ON CONFLICT (id) DO NOTHING;
