INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5c09ba75-8a71-557f-96bb-686fd9c3c311', 'f13c3417-7533-5e57-81f4-85dd9bbd88b6', '{"en": "The dua of Yunus begins with…?", "bn": "ইউনুস (আ.)-এর দোয়া শুরু হয়…?"}', '{"en": "\"…I have indeed been among the wrongdoers.\"", "bn": "\"…নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।\""}', 'Quran 21:87', 8) ON CONFLICT (id) DO NOTHING;
