INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7495f2ab-4ca5-5eea-8e91-14eec36feb09', '5bddb2c2-4d54-5a33-914e-b4e940a8b24b', '{"en": "How many ayahs does the Quran have in the common (Kufan) count?", "bn": "প্রচলিত (কুফি) গণনায় কুরআনে কতটি আয়াত?"}', '{"en": "6,236 in the Kufan count used in most printed mushafs (Hafs).", "bn": "বেশিরভাগ মুদ্রিত মুসহাফে (হাফস) ব্যবহৃত কুফি গণনায় ৬,২৩৬।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
