INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('928a90a0-61db-5616-9e3a-9918e2026540', '5bddb2c2-4d54-5a33-914e-b4e940a8b24b', '{"en": "Under which caliph was the Quran first gathered into one book?", "bn": "কোন খলিফার সময়ে কুরআন প্রথম এক গ্রন্থে সংকলিত হয়?"}', '{"en": "After many reciters were martyred at Yamamah, ‘Umar urged Abu Bakr to gather it.", "bn": "ইয়ামামায় বহু কারি শহিদ হলে উমর (রা.) আবু বকর (রা.)-কে সংকলনের পরামর্শ দেন।"}', 'Sahih al-Bukhari 4986', 2) ON CONFLICT (id) DO NOTHING;
