INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('eabc32cd-33c8-5720-91fa-81308fa0e0e6', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "What is the bridge over Hell called?", "bn": "জাহান্নামের ওপরের সেতুকে কী বলে?"}', '{"en": "As-Sirat is laid over Hell and everyone passes over it.", "bn": "জাহান্নামের ওপর সিরাত স্থাপন করা হবে এবং সবাই তা পার হবে।"}', 'Sahih al-Bukhari 806', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0803ea3e-1a01-512c-b944-2c3ea0edf505', 'eabc32cd-33c8-5720-91fa-81308fa0e0e6', '{"en": "As-Sirat", "bn": "সিরাত"}', true, 1), ('af410e63-01af-5eff-927f-51286496eb63', 'eabc32cd-33c8-5720-91fa-81308fa0e0e6', '{"en": "Al-Mizan", "bn": "মিজান"}', false, 2), ('bf2afa5a-0770-5d27-8f17-0080f37eb543', 'eabc32cd-33c8-5720-91fa-81308fa0e0e6', '{"en": "Al-Hawd", "bn": "হাউজ"}', false, 3), ('d5647df9-177d-5ba4-90f8-d8d0d926dff1', 'eabc32cd-33c8-5720-91fa-81308fa0e0e6', '{"en": "Al-A‘raf", "bn": "আরাফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6ab03b10-a5b9-5e9e-a0c6-8942b4c9e94c', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "Deeds are weighed on…?", "bn": "আমল কিসে ওজন করা হবে?"}', '{"en": "\"And We place the scales of justice for the Day of Resurrection.\"", "bn": "\"আর কিয়ামতের দিন আমি ন্যায়বিচারের দাঁড়িপাল্লা স্থাপন করব।\""}', 'Quran 21:47', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8704684b-348e-5ddf-9383-a88ed4b63a67', '6ab03b10-a5b9-5e9e-a0c6-8942b4c9e94c', '{"en": "Al-Mizan (the Scale)", "bn": "মিজান (দাঁড়িপাল্লা)"}', true, 1), ('1714b120-681d-50ce-b679-42035de785aa', '6ab03b10-a5b9-5e9e-a0c6-8942b4c9e94c', '{"en": "As-Sirat", "bn": "সিরাত"}', false, 2), ('6e9f4874-1b88-554c-bb2f-9bc7d9c4cb3f', '6ab03b10-a5b9-5e9e-a0c6-8942b4c9e94c', '{"en": "The Kursi", "bn": "কুরসি"}', false, 3), ('06b1717f-eb9c-5f45-89bb-1a227aea6add', '6ab03b10-a5b9-5e9e-a0c6-8942b4c9e94c', '{"en": "The Book", "bn": "আমলনামা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e2748567-374f-5385-9c1f-837d96aaf39e', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "What is the Prophet’s ﷺ pool on the Day of Judgement called?", "bn": "কিয়ামতের দিন নবীজির ﷺ হাউজের নাম কী?"}', '{"en": "Its water is whiter than milk; whoever drinks will never thirst again.", "bn": "এর পানি দুধের চেয়ে সাদা; যে পান করবে সে আর কখনো তৃষ্ণার্ত হবে না।"}', 'Sahih al-Bukhari 6579', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b6c9eb31-c831-5e46-9884-fc682019c1c2', 'e2748567-374f-5385-9c1f-837d96aaf39e', '{"en": "Al-Kawthar (al-Hawd)", "bn": "হাউজে কাউসার"}', true, 1), ('3018e425-2376-5369-b19d-5b698e5fe28f', 'e2748567-374f-5385-9c1f-837d96aaf39e', '{"en": "Zamzam", "bn": "যমযম"}', false, 2), ('dafdd73b-afaf-5c9f-900f-a7d01e4359f9', 'e2748567-374f-5385-9c1f-837d96aaf39e', '{"en": "Salsabil", "bn": "সালসাবিল"}', false, 3), ('8d9755cb-fa4b-5696-9d61-8e030e49a9c7', 'e2748567-374f-5385-9c1f-837d96aaf39e', '{"en": "Tasnim", "bn": "তাসনিম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('f2679e2d-2667-5ec2-abeb-b57710cc81e6', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "The Resurrection begins when what is blown?", "bn": "কী ফুঁ দেওয়ার মাধ্যমে কিয়ামত শুরু হবে?"}', '{"en": "\"And the Trumpet will be blown…\"", "bn": "\"আর শিঙ্গায় ফুঁ দেওয়া হবে…\""}', 'Quran 39:68', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b2613126-a278-56c7-a3ec-2ba10639a7f6', 'f2679e2d-2667-5ec2-abeb-b57710cc81e6', '{"en": "The Trumpet (as-Sur)", "bn": "শিঙ্গা (সুর)"}', true, 1), ('83e402bc-98c0-552c-8408-5986b7b719cd', 'f2679e2d-2667-5ec2-abeb-b57710cc81e6', '{"en": "A wind", "bn": "বাতাস"}', false, 2), ('6d75726a-3d78-5ec1-bb72-63dc72084c3d', 'f2679e2d-2667-5ec2-abeb-b57710cc81e6', '{"en": "A drum", "bn": "ঢোল"}', false, 3), ('cea594af-b688-53ad-aba5-137019010c36', 'f2679e2d-2667-5ec2-abeb-b57710cc81e6', '{"en": "A whistle", "bn": "বাঁশি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ef1cf256-0a85-51a1-9c10-ad6d6297b574', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "What is the highest level of Paradise?", "bn": "জান্নাতের সর্বোচ্চ স্তর কোনটি?"}', '{"en": "\"When you ask Allah, ask Him for al-Firdaws; it is the middle and highest of Paradise.\"", "bn": "\"আল্লাহর কাছে চাইলে ফিরদাউস চাও; এটি জান্নাতের মধ্যবর্তী ও সর্বোচ্চ।\""}', 'Sahih al-Bukhari 2790', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('25062fd9-43cd-58e5-b3fe-9dc0718d0f35', 'ef1cf256-0a85-51a1-9c10-ad6d6297b574', '{"en": "Al-Firdaws", "bn": "ফিরদাউস"}', true, 1), ('6a1e87c8-e6ac-5b2c-bbbb-984349e71c06', 'ef1cf256-0a85-51a1-9c10-ad6d6297b574', '{"en": "Adn", "bn": "আদন"}', false, 2), ('50332e23-ac0a-559a-8084-d3f9683e9e7c', 'ef1cf256-0a85-51a1-9c10-ad6d6297b574', '{"en": "Na‘im", "bn": "নাঈম"}', false, 3), ('0181de0f-486c-59dc-bb16-afeb93caf005', 'ef1cf256-0a85-51a1-9c10-ad6d6297b574', '{"en": "Ma’wa", "bn": "মাওয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1c2e4eb2-beae-5bbe-ad00-467763742a4b', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "Through which gate of Paradise will the fasting people enter?", "bn": "রোজাদাররা জান্নাতের কোন দরজা দিয়ে প্রবেশ করবে?"}', '{"en": "\"In Paradise there is a gate called ar-Rayyan; only those who fast enter through it.\"", "bn": "\"জান্নাতে রাইয়ান নামে একটি দরজা আছে; শুধু রোজাদাররাই তা দিয়ে প্রবেশ করবে।\""}', 'Sahih al-Bukhari 1896', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('12ac070f-ec65-512e-aaa0-e768709cefcd', '1c2e4eb2-beae-5bbe-ad00-467763742a4b', '{"en": "Ar-Rayyan", "bn": "রাইয়ান"}', true, 1), ('0ce4ee1e-2a75-543e-a528-ad2c8557ae81', '1c2e4eb2-beae-5bbe-ad00-467763742a4b', '{"en": "As-Salam", "bn": "সালাম"}', false, 2), ('4037bbb8-f51b-5dd6-9196-746dc9917c04', '1c2e4eb2-beae-5bbe-ad00-467763742a4b', '{"en": "Al-Firdaws", "bn": "ফিরদাউস"}', false, 3), ('326fb233-816a-55d5-b58e-ce40a418af85', '1c2e4eb2-beae-5bbe-ad00-467763742a4b', '{"en": "Al-Kawthar", "bn": "কাওসার"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ae4882a5-bae5-5199-9476-8e8f02d11fd5', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "Receiving one’s record in the right hand means…?", "bn": "ডান হাতে আমলনামা পাওয়ার অর্থ…?"}', '{"en": "\"As for him who is given his record in his right hand, he will say: Here, read my record!\"", "bn": "\"যাকে তার আমলনামা ডান হাতে দেওয়া হবে, সে বলবে: এই নাও, আমার আমলনামা পড়ো!\""}', 'Quran 69:19', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('86810626-b58c-574a-aff5-6544f6e52f6c', 'ae4882a5-bae5-5199-9476-8e8f02d11fd5', '{"en": "Success", "bn": "সফলতা"}', true, 1), ('175e7420-43a3-57bc-a203-b748cbac22d1', 'ae4882a5-bae5-5199-9476-8e8f02d11fd5', '{"en": "Loss", "bn": "ক্ষতি"}', false, 2), ('cb8a560f-7d8c-5eb5-96c6-559ea87b1fc7', 'ae4882a5-bae5-5199-9476-8e8f02d11fd5', '{"en": "Waiting", "bn": "অপেক্ষা"}', false, 3), ('84b6790e-6719-53a9-9deb-a11d092a80d5', 'ae4882a5-bae5-5199-9476-8e8f02d11fd5', '{"en": "Nothing", "bn": "কিছুই না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6f5eb96d-0ea1-5ae0-a14f-8b7ca27eeae5', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "Who will have the greatest intercession (shafa‘ah) on that Day?", "bn": "সেদিন সর্বশ্রেষ্ঠ শাফাআত কার?"}', '{"en": "People will go from prophet to prophet until they come to Muhammad ﷺ.", "bn": "মানুষ নবী থেকে নবীর কাছে যাবে, অবশেষে মুহাম্মাদ ﷺ-এর কাছে আসবে।"}', 'Sahih al-Bukhari 4712', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cfb6f019-b18d-5e40-8b2b-936bbd413bc0', '6f5eb96d-0ea1-5ae0-a14f-8b7ca27eeae5', '{"en": "Muhammad ﷺ", "bn": "মুহাম্মাদ ﷺ"}', true, 1), ('cd58d92c-30a9-5f52-b637-f04e70312525', '6f5eb96d-0ea1-5ae0-a14f-8b7ca27eeae5', '{"en": "Adam", "bn": "আদম"}', false, 2), ('55247d44-790f-5f16-83f5-a425bbf34bbd', '6f5eb96d-0ea1-5ae0-a14f-8b7ca27eeae5', '{"en": "Nuh", "bn": "নুহ"}', false, 3), ('0e80e0a6-bf14-594f-8509-9bfa3fa865cf', '6f5eb96d-0ea1-5ae0-a14f-8b7ca27eeae5', '{"en": "Isa", "bn": "ঈসা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('efe2fe24-a9b1-52e3-ab84-67f888dfd0c6', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "What is the stage between death and the Resurrection called?", "bn": "মৃত্যু ও পুনরুত্থানের মাঝের জগৎকে কী বলে?"}', '{"en": "\"…and behind them is a barrier (barzakh) until the Day they are resurrected.\"", "bn": "\"…আর তাদের সামনে পুনরুত্থান দিবস পর্যন্ত এক অন্তরাল (বারযাখ)।\""}', 'Quran 23:100', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('0d33b7f7-d8a1-586d-af93-1555f5ad9c11', 'efe2fe24-a9b1-52e3-ab84-67f888dfd0c6', '{"en": "Barzakh", "bn": "বারযাখ"}', true, 1), ('84053b91-2be5-5c12-b216-8aa195ce3f16', 'efe2fe24-a9b1-52e3-ab84-67f888dfd0c6', '{"en": "Dunya", "bn": "দুনিয়া"}', false, 2), ('ade81808-b770-59f7-8a21-588b0f5a195e', 'efe2fe24-a9b1-52e3-ab84-67f888dfd0c6', '{"en": "Mahshar", "bn": "হাশর"}', false, 3), ('9c8761f2-35f7-5c1f-94cb-322b8d3630c9', 'efe2fe24-a9b1-52e3-ab84-67f888dfd0c6', '{"en": "A‘raf", "bn": "আরাফ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8fee9d6d-a602-5173-ad00-574ae7ecbe20', '051f5652-815b-5d9c-b5ad-9b4453f041f9', '{"en": "The Quran describes a Day whose length is…?", "bn": "কুরআন এমন এক দিনের বর্ণনা দেয় যার দৈর্ঘ্য…?"}', '{"en": "\"…in a Day whose measure is fifty thousand years.\"", "bn": "\"…এমন এক দিনে যার পরিমাণ পঞ্চাশ হাজার বছর।\""}', 'Quran 70:4', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('42d8f8bc-4696-513f-bfd8-bc5474277a54', '8fee9d6d-a602-5173-ad00-574ae7ecbe20', '{"en": "Fifty thousand years", "bn": "পঞ্চাশ হাজার বছর"}', true, 1), ('acc9f7a8-431f-594e-936b-e7f42129bb54', '8fee9d6d-a602-5173-ad00-574ae7ecbe20', '{"en": "One week", "bn": "এক সপ্তাহ"}', false, 2), ('11d359c7-9488-5771-bbea-17a4f8322f9e', '8fee9d6d-a602-5173-ad00-574ae7ecbe20', '{"en": "One year", "bn": "এক বছর"}', false, 3), ('67885eb0-e580-53b5-9b35-7778e887feee', '8fee9d6d-a602-5173-ad00-574ae7ecbe20', '{"en": "One hour", "bn": "এক ঘণ্টা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Angels & the unseen", "bn": "ফেরেশতা ও অদৃশ্য জগৎ"}', 'general', 'easy', NULL, 10, 'in_review', 27) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8c8d4e54-be9d-5018-a19c-43fd96710cb5', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Angels were created from…?", "bn": "ফেরেশতারা কী থেকে সৃষ্ট?"}', '{"en": "\"Angels were created from light, jinn from smokeless fire, and Adam from what you have been told.\"", "bn": "\"ফেরেশতারা নূর থেকে, জিন ধোঁয়াহীন আগুন থেকে, আর আদম তা থেকে যা তোমাদের বলা হয়েছে।\""}', 'Sahih Muslim 2996', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('acc9a800-c265-5102-b854-ec533f946fc7', '8c8d4e54-be9d-5018-a19c-43fd96710cb5', '{"en": "Light", "bn": "নূর (আলো)"}', true, 1), ('1f13e55b-0dfa-5062-b0e4-284972c85b97', '8c8d4e54-be9d-5018-a19c-43fd96710cb5', '{"en": "Fire", "bn": "আগুন"}', false, 2), ('3732bd82-7f0e-5b7b-85b3-b60a6058e2be', '8c8d4e54-be9d-5018-a19c-43fd96710cb5', '{"en": "Clay", "bn": "মাটি"}', false, 3), ('8b6a0a09-bcb7-5d38-82b2-01540ae7c91c', '8c8d4e54-be9d-5018-a19c-43fd96710cb5', '{"en": "Water", "bn": "পানি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('972131ed-ea2a-5cc0-8545-6073b9dd722c', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Jinn were created from…?", "bn": "জিন কী থেকে সৃষ্ট?"}', '{"en": "\"And He created the jinn from a smokeless flame of fire.\"", "bn": "\"আর তিনি জিনকে সৃষ্টি করেছেন ধোঁয়াহীন অগ্নিশিখা থেকে।\""}', 'Quran 55:15', 2) ON CONFLICT (id) DO NOTHING;
