INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0548077f-2d43-5092-8291-18984b85e8f6', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Adam was created from…?", "bn": "আদম (আ.) কী থেকে সৃষ্ট?"}', '{"en": "\"He created man from clay like pottery.\"", "bn": "\"তিনি মানুষকে সৃষ্টি করেছেন পোড়ামাটির মতো শুকনো মাটি থেকে।\""}', 'Quran 55:14', 3) ON CONFLICT (id) DO NOTHING;
