INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9f6a0898-49ba-57da-8dee-8188a9e340e0', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Which angel is called \"the trustworthy spirit\" (ar-Ruh al-Amin)?", "bn": "কোন ফেরেশতাকে \"রুহুল আমিন\" (বিশ্বস্ত আত্মা) বলা হয়?"}', '{"en": "\"The trustworthy spirit has brought it down upon your heart.\"", "bn": "\"বিশ্বস্ত আত্মা (রুহুল আমিন) এটি তোমার হৃদয়ে নাজিল করেছেন।\""}', 'Quran 26:193–194', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('671539ac-4801-55c0-9987-579ea50af42f', '9f6a0898-49ba-57da-8dee-8188a9e340e0', '{"en": "Jibril", "bn": "জিবরাইল"}', true, 1), ('1cefe9e8-5501-5ebc-9ffd-33718ff19359', '9f6a0898-49ba-57da-8dee-8188a9e340e0', '{"en": "Mika’il", "bn": "মিকাইল"}', false, 2), ('8af274c3-9a58-5f9a-9262-8dad539372d6', '9f6a0898-49ba-57da-8dee-8188a9e340e0', '{"en": "Malik", "bn": "মালিক"}', false, 3), ('63f9ab43-a8b7-53ac-9ede-6594aeb48bc3', '9f6a0898-49ba-57da-8dee-8188a9e340e0', '{"en": "Ridwan", "bn": "রিদওয়ান"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('455f2ed1-5fab-588c-a746-6c0f8e3ee8c7', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Which two angels question the dead in the grave?", "bn": "কোন দুই ফেরেশতা কবরে মৃতকে প্রশ্ন করেন?"}', '{"en": "They ask: Who is your Lord? What is your religion? Who is your prophet?", "bn": "তাঁরা জিজ্ঞেস করেন: তোমার রব কে? তোমার দ্বীন কী? তোমার নবী কে?"}', 'Jami‘ at-Tirmidhi 1071', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('fc4e2d3e-dd6d-5bbe-80f2-3b0d463acbe6', '455f2ed1-5fab-588c-a746-6c0f8e3ee8c7', '{"en": "Munkar and Nakir", "bn": "মুনকার ও নাকির"}', true, 1), ('b3ecbad7-c4f6-5570-8346-bab28e212daf', '455f2ed1-5fab-588c-a746-6c0f8e3ee8c7', '{"en": "Harut and Marut", "bn": "হারুত ও মারুত"}', false, 2), ('16d4434d-5a07-5ac2-8619-f0aa15cca17c', '455f2ed1-5fab-588c-a746-6c0f8e3ee8c7', '{"en": "Jibril and Mika’il", "bn": "জিবরাইল ও মিকাইল"}', false, 3), ('9d770edb-b776-512b-bfd1-76f4fa40ca97', '455f2ed1-5fab-588c-a746-6c0f8e3ee8c7', '{"en": "Ridwan and Malik", "bn": "রিদওয়ান ও মালিক"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('532c7f46-f80e-5f87-888a-3b18524da32e', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Iblis refused to prostrate to whom?", "bn": "ইবলিস কাকে সিজদা করতে অস্বীকার করেছিল?"}', '{"en": "\"…so they prostrated, except Iblis; he refused and was arrogant.\"", "bn": "\"…তারা সিজদা করল, ইবলিস ছাড়া; সে অস্বীকার করল ও অহংকার করল।\""}', 'Quran 2:34', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9b2d4491-3442-5018-9cbb-d205d9dc07b7', '532c7f46-f80e-5f87-888a-3b18524da32e', '{"en": "Adam", "bn": "আদম"}', true, 1), ('b83f0698-9af4-5680-970b-7d0bdc8d186c', '532c7f46-f80e-5f87-888a-3b18524da32e', '{"en": "Nuh", "bn": "নুহ"}', false, 2), ('3df969b3-fa70-50af-93c8-8260762de605', '532c7f46-f80e-5f87-888a-3b18524da32e', '{"en": "The Ka‘bah", "bn": "কাবা"}', false, 3), ('829675f9-b768-5cb3-a92c-0f94ba607782', '532c7f46-f80e-5f87-888a-3b18524da32e', '{"en": "The angels", "bn": "ফেরেশতাদের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('98848c91-41d9-56ee-b894-4f167914e6ef', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Iblis was one of the…?", "bn": "ইবলিস কাদের অন্তর্ভুক্ত ছিল?"}', '{"en": "\"…except Iblis. He was of the jinn.\"", "bn": "\"…ইবলিস ছাড়া। সে ছিল জিনদের একজন।\""}', 'Quran 18:50', 7) ON CONFLICT (id) DO NOTHING;
