INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('346e2c01-f815-51e7-bf48-e40c0838abd5', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Do angels disobey Allah’s commands?", "bn": "ফেরেশতারা কি আল্লাহর আদেশ অমান্য করেন?"}', '{"en": "\"…they do not disobey Allah in what He commands them, and do what they are commanded.\"", "bn": "\"…তারা আল্লাহর আদেশ অমান্য করে না এবং যা আদেশ করা হয় তা-ই করে।\""}', 'Quran 66:6', 8) ON CONFLICT (id) DO NOTHING;
