INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('22dc4ad1-02be-596b-9463-8ac1342c0ff5', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "What does the Quran call the angel who takes souls?", "bn": "রুহ কবজকারী ফেরেশতাকে কুরআনে কী বলা হয়েছে?"}', '{"en": "\"The Angel of Death who has been entrusted with you will take you.\"", "bn": "\"তোমাদের দায়িত্বে নিযুক্ত মৃত্যুর ফেরেশতা তোমাদের প্রাণ হরণ করবে।\""}', 'Quran 32:11', 9) ON CONFLICT (id) DO NOTHING;
