INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('32aa2716-c42f-5cd3-a151-869f13b7aaa4', '27172757-49b1-5112-8144-0e7ea87cbc03', '{"en": "Harut and Marut were sent down in…?", "bn": "হারুত ও মারুতকে কোথায় পাঠানো হয়েছিল?"}', '{"en": "\"…the two angels at Babylon, Harut and Marut.\"", "bn": "\"…বাবেলের দুই ফেরেশতা হারুত ও মারুত।\""}', 'Quran 2:102', 10) ON CONFLICT (id) DO NOTHING;
