INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Fasting: the basics", "bn": "রোজার মৌলিক বিধান"}', 'fiqh', 'medium', NULL, 10, 'in_review', 28) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('016c2b41-0056-5010-a216-6e7c0b72a0eb', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "If someone eats forgetfully while fasting, then…?", "bn": "রোজা অবস্থায় কেউ ভুলে খেয়ে ফেললে…?"}', '{"en": "\"…let him complete his fast, for Allah fed him and gave him drink.\"", "bn": "\"…সে যেন রোজা পূর্ণ করে, কারণ আল্লাহই তাকে খাইয়েছেন ও পান করিয়েছেন।\""}', 'Sahih al-Bukhari 1933', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('df24f353-9be0-5564-a68a-1aaae590dd7e', '016c2b41-0056-5010-a216-6e7c0b72a0eb', '{"en": "The fast continues", "bn": "রোজা চলবে"}', true, 1), ('f69d65d6-f165-5f53-9cc1-0d6bbd8e96c8', '016c2b41-0056-5010-a216-6e7c0b72a0eb', '{"en": "The fast is broken", "bn": "রোজা ভেঙে যাবে"}', false, 2), ('5614e882-ffd2-5b61-a0a4-72da13e20502', '016c2b41-0056-5010-a216-6e7c0b72a0eb', '{"en": "He must fast 60 days", "bn": "৬০ দিন রোজা রাখতে হবে"}', false, 3), ('fd903d12-e824-5583-b6d8-e3a808efde16', '016c2b41-0056-5010-a216-6e7c0b72a0eb', '{"en": "He must give charity", "bn": "সদকা দিতে হবে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('43ff62c6-dd26-5a62-b7fe-0cf8ac138f16', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "When does the fast begin each day?", "bn": "প্রতিদিন রোজা কখন শুরু হয়?"}', '{"en": "\"…until the white thread of dawn becomes distinct to you from the black thread.\"", "bn": "\"…যতক্ষণ না ভোরের সাদা রেখা কালো রেখা থেকে স্পষ্ট হয়।\""}', 'Quran 2:187', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('ac7f57de-e448-5f99-8a52-b91463249f2f', '43ff62c6-dd26-5a62-b7fe-0cf8ac138f16', '{"en": "At true dawn (Fajr)", "bn": "সুবহে সাদিক (ফজর)"}', true, 1), ('03149210-9c91-57c6-9bfd-7392563edc04', '43ff62c6-dd26-5a62-b7fe-0cf8ac138f16', '{"en": "At sunrise", "bn": "সূর্যোদয়ে"}', false, 2), ('7b623650-914c-5f96-90c7-c2a8da53ecf8', '43ff62c6-dd26-5a62-b7fe-0cf8ac138f16', '{"en": "At midnight", "bn": "মধ্যরাতে"}', false, 3), ('ce67a20f-c840-5882-a83c-b11f7157196c', '43ff62c6-dd26-5a62-b7fe-0cf8ac138f16', '{"en": "At Dhuhr", "bn": "যোহরে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a247d9e5-4019-58e8-a007-062682ad7de6', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "When does the fast end?", "bn": "রোজা কখন শেষ হয়?"}', '{"en": "\"…then complete the fast until the night.\"", "bn": "\"…তারপর রাত পর্যন্ত রোজা পূর্ণ করো।\""}', 'Quran 2:187', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f834dfdb-e566-5462-a6aa-8bc64efc4000', 'a247d9e5-4019-58e8-a007-062682ad7de6', '{"en": "At sunset", "bn": "সূর্যাস্তে"}', true, 1), ('d3a747a9-b19e-5a62-9f93-efb8166caff7', 'a247d9e5-4019-58e8-a007-062682ad7de6', '{"en": "At Asr", "bn": "আসরে"}', false, 2), ('0a048b4f-8bde-5612-aa8b-5dc68e4c3bb9', 'a247d9e5-4019-58e8-a007-062682ad7de6', '{"en": "At Isha", "bn": "ইশায়"}', false, 3), ('bd02d5f2-28f1-5b99-b70f-aeea2bc616bf', 'a247d9e5-4019-58e8-a007-062682ad7de6', '{"en": "At midnight", "bn": "মধ্যরাতে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('271c9357-8fe8-5ed0-939b-acfbf64d0d93', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Who may skip fasting in Ramadan and make it up later?", "bn": "কে রমজানে রোজা না রেখে পরে কাজা করতে পারে?"}', '{"en": "\"…whoever is ill or on a journey, then an equal number of other days.\"", "bn": "\"…যে অসুস্থ বা সফরে থাকে, সে অন্য দিনে সমান সংখ্যা পূর্ণ করবে।\""}', 'Quran 2:184', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('bf253682-e0e9-5e0f-a045-2bde445dde55', '271c9357-8fe8-5ed0-939b-acfbf64d0d93', '{"en": "The sick and the traveller", "bn": "অসুস্থ ও মুসাফির"}', true, 1), ('26d7bd07-f4a4-5ee1-95ad-8ba2ba1e1b00', '271c9357-8fe8-5ed0-939b-acfbf64d0d93', '{"en": "Anyone who is busy", "bn": "যে ব্যস্ত"}', false, 2), ('0858012d-d368-5df1-a252-661f55a7ceb5', '271c9357-8fe8-5ed0-939b-acfbf64d0d93', '{"en": "Students", "bn": "ছাত্ররা"}', false, 3), ('8f577874-6241-5043-ac71-aaa24cc35855', '271c9357-8fe8-5ed0-939b-acfbf64d0d93', '{"en": "Nobody", "bn": "কেউ না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('17ba60d7-ea9b-5b5c-af4e-70ceecb8515b', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Someone who can never fast (e.g. very old) should…?", "bn": "যে কখনো রোজা রাখতে পারবে না (যেমন অতি বৃদ্ধ), তার করণীয়…?"}', '{"en": "\"…a ransom: feeding a poor person (each day).\"", "bn": "\"…ফিদিয়া: (প্রতিদিন) একজন মিসকিনকে খাওয়ানো।\""}', 'Quran 2:184', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('d5425911-0daf-554b-aaf1-4b2b2f0c0a10', '17ba60d7-ea9b-5b5c-af4e-70ceecb8515b', '{"en": "Feed a poor person for each day", "bn": "প্রতিদিনের বদলে একজন গরিবকে খাওয়ানো"}', true, 1), ('ff321706-3c7c-5927-8ff3-a40faf708880', '17ba60d7-ea9b-5b5c-af4e-70ceecb8515b', '{"en": "Pray extra", "bn": "বেশি নামাজ পড়া"}', false, 2), ('2fc7ec77-0fa6-523c-b80c-c4a9e075f473', '17ba60d7-ea9b-5b5c-af4e-70ceecb8515b', '{"en": "Do nothing", "bn": "কিছুই না"}', false, 3), ('afc14218-d38d-5bf8-bd22-cd8fc649c93f', '17ba60d7-ea9b-5b5c-af4e-70ceecb8515b', '{"en": "Fast at night", "bn": "রাতে রোজা রাখা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('65815f1e-c2ed-55c4-a1f1-0b4038f36fb1', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "What is the sunnah about iftar time?", "bn": "ইফতারের সময় নিয়ে সুন্নাহ কী?"}', '{"en": "\"People will remain upon good as long as they hasten the iftar.\"", "bn": "\"মানুষ ততদিন কল্যাণে থাকবে যতদিন তারা দ্রুত ইফতার করবে।\""}', 'Sahih al-Bukhari 1957', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cca4306e-72cf-5f65-aca0-df2173ac3a50', '65815f1e-c2ed-55c4-a1f1-0b4038f36fb1', '{"en": "Hasten it at sunset", "bn": "সূর্যাস্ত হলেই দ্রুত ইফতার"}', true, 1), ('d4272be7-d1c8-5374-918e-b7173bddeefe', '65815f1e-c2ed-55c4-a1f1-0b4038f36fb1', '{"en": "Delay it until Isha", "bn": "ইশা পর্যন্ত দেরি"}', false, 2), ('883c58d1-2b51-5a53-bd40-aeab03ae3b08', '65815f1e-c2ed-55c4-a1f1-0b4038f36fb1', '{"en": "Eat it at midnight", "bn": "মধ্যরাতে খাওয়া"}', false, 3), ('fadce842-853f-5cb4-a336-01d1e603ad1f', '65815f1e-c2ed-55c4-a1f1-0b4038f36fb1', '{"en": "Skip it", "bn": "বাদ দেওয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ed151dc2-5c13-5ba1-8b26-ef292d21145a', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Fasting Ramadan with faith and hoping for reward brings…?", "bn": "ঈমান ও সওয়াবের আশায় রমজানের রোজা রাখলে কী হয়?"}', '{"en": "\"…his previous sins will be forgiven.\"", "bn": "\"…তার আগের গুনাহ মাফ করে দেওয়া হবে।\""}', 'Sahih al-Bukhari 38', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b68bae3a-cdc6-59b3-9233-26dbe08985e0', 'ed151dc2-5c13-5ba1-8b26-ef292d21145a', '{"en": "Forgiveness of past sins", "bn": "আগের গুনাহ মাফ"}', true, 1), ('129c985e-653a-563d-ab93-93a6cace0196', 'ed151dc2-5c13-5ba1-8b26-ef292d21145a', '{"en": "Wealth", "bn": "সম্পদ"}', false, 2), ('bbcecdac-6b55-5624-9850-ac849bcb913f', 'ed151dc2-5c13-5ba1-8b26-ef292d21145a', '{"en": "Fame", "bn": "খ্যাতি"}', false, 3), ('35472aa5-9fff-5c7b-817a-99ac3e217d85', 'ed151dc2-5c13-5ba1-8b26-ef292d21145a', '{"en": "Nothing special", "bn": "বিশেষ কিছু না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('b0364ff8-58e5-5ef1-bc83-7abead7a712d', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Allah says in a hadith qudsi, \"Fasting is for Me and…\"", "bn": "হাদিসে কুদসিতে আল্লাহ বলেন, \"রোজা আমার জন্য এবং…\""}', '{"en": "A fasting person’s reward is given by Allah Himself.", "bn": "রোজাদারের প্রতিদান আল্লাহ নিজেই দেবেন।"}', 'Sahih al-Bukhari 1904', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('74d346b6-8e5e-54f5-84c3-2bcc34aea4a5', 'b0364ff8-58e5-5ef1-bc83-7abead7a712d', '{"en": "…I will reward it", "bn": "…আমিই এর প্রতিদান দেব"}', true, 1), ('496c3c61-29d5-568a-94c5-7d4d0461c0d5', 'b0364ff8-58e5-5ef1-bc83-7abead7a712d', '{"en": "…it is easy", "bn": "…এটি সহজ"}', false, 2), ('8b15f524-74ef-50bd-8e33-1e92bfbf2be4', 'b0364ff8-58e5-5ef1-bc83-7abead7a712d', '{"en": "…it is optional", "bn": "…এটি ঐচ্ছিক"}', false, 3), ('6c1ee4f8-ed0d-56a6-9b4f-dedfd3960809', 'b0364ff8-58e5-5ef1-bc83-7abead7a712d', '{"en": "…it is once a year", "bn": "…এটি বছরে একবার"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('88a541ab-3dd4-5a98-9f96-c2b919605dd9', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Staying in the masjid for worship in the last ten days is called…?", "bn": "শেষ দশকে ইবাদতের জন্য মসজিদে অবস্থানকে কী বলে?"}', '{"en": "The Prophet ﷺ did i‘tikaf in the last ten days of Ramadan.", "bn": "নবী ﷺ রমজানের শেষ দশকে ইতিকাফ করতেন।"}', 'Sahih al-Bukhari 2026', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c4737548-2e97-5613-911c-6bcb8a62d2df', '88a541ab-3dd4-5a98-9f96-c2b919605dd9', '{"en": "I‘tikaf", "bn": "ইতিকাফ"}', true, 1), ('adf259c7-c3d8-59ec-8823-952e839e4be5', '88a541ab-3dd4-5a98-9f96-c2b919605dd9', '{"en": "Tarawih", "bn": "তারাবিহ"}', false, 2), ('50071bf7-c272-5d55-a720-f8fe51e4d90e', '88a541ab-3dd4-5a98-9f96-c2b919605dd9', '{"en": "Hajj", "bn": "হজ"}', false, 3), ('71c9f921-0494-521a-9d38-1a679063904a', '88a541ab-3dd4-5a98-9f96-c2b919605dd9', '{"en": "Qiyam", "bn": "কিয়াম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a9b3f7ce-77ce-5394-8efa-bae29901da0f', 'a64ad3da-0eb4-58d7-a966-143e9d38a7fe', '{"en": "Why was fasting prescribed, according to 2:183?", "bn": "২:১৮৩ অনুযায়ী রোজা কেন ফরজ করা হয়েছে?"}', '{"en": "\"…as it was prescribed for those before you, so that you may attain taqwa.\"", "bn": "\"…যেমন তোমাদের পূর্ববর্তীদের ওপর ফরজ করা হয়েছিল, যাতে তোমরা তাকওয়া অর্জন করতে পারো।\""}', 'Quran 2:183', 10) ON CONFLICT (id) DO NOTHING;
