INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a0e9a8a4-4a3b-591a-89c8-18c10873e5a0', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "Truthfulness leads to righteousness, and righteousness leads to…?", "bn": "সত্যবাদিতা নেকির দিকে নিয়ে যায়, আর নেকি নিয়ে যায়…?"}', '{"en": "\"Truthfulness leads to righteousness, and righteousness leads to Paradise.\"", "bn": "\"সত্য নেকির পথ দেখায়, আর নেকি জান্নাতের পথ দেখায়।\""}', 'Sahih al-Bukhari 6094', 3) ON CONFLICT (id) DO NOTHING;
