INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('50be8627-6501-52a6-8b66-ab34125e0428', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "What must we never say to our parents, even when they are old?", "bn": "বাবা-মা বৃদ্ধ হলেও তাদের কী বলা যাবে না?"}', '{"en": "\"…do not say to them uff, nor repel them, but speak to them a noble word.\"", "bn": "\"…তাদের উফ বোলো না, ধমক দিয়ো না, বরং সম্মানের সাথে কথা বলো।\""}', 'Quran 17:23', 4) ON CONFLICT (id) DO NOTHING;
