INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('0a54fb03-6745-5122-a128-d9b1628a9590', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "Who is truly strong, according to the hadith?", "bn": "হাদিস অনুযায়ী প্রকৃত শক্তিশালী কে?"}', '{"en": "\"The strong one is not the good wrestler; the strong one controls himself when angry.\"", "bn": "\"কুস্তিতে জয়ী শক্তিশালী নয়; শক্তিশালী সে, যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে।\""}', 'Sahih al-Bukhari 6114', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('9dc45f5d-7c00-59a7-8415-8e295de2e208', '0a54fb03-6745-5122-a128-d9b1628a9590', '{"en": "One who controls himself when angry", "bn": "যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে"}', true, 1), ('5b357530-f4fa-543e-8cd6-e75c9c49778e', '0a54fb03-6745-5122-a128-d9b1628a9590', '{"en": "One who wins every fight", "bn": "যে সব লড়াইয়ে জেতে"}', false, 2), ('985db51c-6240-5643-ba8a-ac758bb64be3', '0a54fb03-6745-5122-a128-d9b1628a9590', '{"en": "One who lifts heavy weights", "bn": "যে ভারী বোঝা তোলে"}', false, 3), ('78dfe179-2ca7-52d7-854a-fcc9cbb8ef7c', '0a54fb03-6745-5122-a128-d9b1628a9590', '{"en": "One who shouts loudly", "bn": "যে জোরে চিৎকার করে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9ded61b5-dbad-527a-93b4-3d96e034be43', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "Keeping ties with relatives increases…?", "bn": "আত্মীয়তার সম্পর্ক রক্ষা করলে কী বাড়ে?"}', '{"en": "\"Whoever wishes for more provision and a longer life, let him keep ties of kinship.\"", "bn": "\"যে রিজিক ও আয়ু বৃদ্ধি চায়, সে যেন আত্মীয়তার সম্পর্ক রক্ষা করে।\""}', 'Sahih al-Bukhari 5986', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('4a1d16ab-8489-541e-8b92-ecc1f17a95a8', '9ded61b5-dbad-527a-93b4-3d96e034be43', '{"en": "Provision and lifespan", "bn": "রিজিক ও আয়ু"}', true, 1), ('8a7ce4f0-a2bc-53c9-962a-5086d7bdaf8d', '9ded61b5-dbad-527a-93b4-3d96e034be43', '{"en": "Worries", "bn": "দুশ্চিন্তা"}', false, 2), ('2d4a32f3-ddf9-5291-823b-6a612ce26d89', '9ded61b5-dbad-527a-93b4-3d96e034be43', '{"en": "Debts", "bn": "ঋণ"}', false, 3), ('ade05f37-6557-5413-850e-97905391489f', '9ded61b5-dbad-527a-93b4-3d96e034be43', '{"en": "Enemies", "bn": "শত্রু"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('7cc7d1f2-37e9-5c42-aacd-415d0c6d144e', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "The best of you, said the Prophet ﷺ, are those who are best to…?", "bn": "নবী ﷺ বলেছেন, তোমাদের মধ্যে উত্তম সে, যে সবচেয়ে উত্তম…?"}', '{"en": "\"…and I am the best of you to my family.\"", "bn": "\"…আর আমি আমার পরিবারের কাছে তোমাদের মধ্যে সর্বোত্তম।\""}', 'Jami‘ at-Tirmidhi 3895', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('96376cfd-bdd1-5a08-bab4-240effab0d84', '7cc7d1f2-37e9-5c42-aacd-415d0c6d144e', '{"en": "Their families", "bn": "নিজ পরিবারের কাছে"}', true, 1), ('ce41ad1a-e951-5465-a0e3-9a0b80d72468', '7cc7d1f2-37e9-5c42-aacd-415d0c6d144e', '{"en": "Their bosses", "bn": "নিজ কর্তার কাছে"}', false, 2), ('965cea10-fb0a-5012-b877-b2b0d0c3431b', '7cc7d1f2-37e9-5c42-aacd-415d0c6d144e', '{"en": "Strangers only", "bn": "শুধু অপরিচিতদের কাছে"}', false, 3), ('41fec53f-48c7-557d-92f0-10586b05beef', '7cc7d1f2-37e9-5c42-aacd-415d0c6d144e', '{"en": "Themselves", "bn": "নিজের কাছে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ee53a495-d072-5f9d-a562-f4cd0d9cdfc9', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "The Quran likens backbiting to…?", "bn": "কুরআন গিবতকে কীসের সাথে তুলনা করেছে?"}', '{"en": "\"…would one of you like to eat the flesh of his dead brother? You would detest it.\"", "bn": "\"…তোমাদের কেউ কি মৃত ভাইয়ের গোশত খেতে পছন্দ করবে? তোমরা তো তা ঘৃণা করো।\""}', 'Quran 49:12', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('44d50099-7697-5638-9ef0-dec182a1e047', 'ee53a495-d072-5f9d-a562-f4cd0d9cdfc9', '{"en": "Eating your dead brother’s flesh", "bn": "মৃত ভাইয়ের গোশত খাওয়া"}', true, 1), ('c47af464-5b23-59a8-93de-f14bf5ab1ad0', 'ee53a495-d072-5f9d-a562-f4cd0d9cdfc9', '{"en": "Drinking water", "bn": "পানি পান"}', false, 2), ('8fd52f5c-eeb5-5c9a-923c-f0f8aa4bd2b0', 'ee53a495-d072-5f9d-a562-f4cd0d9cdfc9', '{"en": "Walking fast", "bn": "দ্রুত হাঁটা"}', false, 3), ('79c64227-5ce6-5b03-a049-cb2991d1d5e7', 'ee53a495-d072-5f9d-a562-f4cd0d9cdfc9', '{"en": "Sleeping late", "bn": "দেরিতে ঘুমানো"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a57ef112-3d8d-538e-8aa2-87fa96a1219a', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "The one who looks after an orphan will be with the Prophet ﷺ in Paradise like…?", "bn": "এতিমের দায়িত্ব যে নেয়, জান্নাতে নবীজির ﷺ সাথে থাকবে যেভাবে…?"}', '{"en": "He ﷺ held up his index and middle fingers together.", "bn": "তিনি ﷺ তর্জনী ও মধ্যমা একসাথে দেখালেন।"}', 'Sahih al-Bukhari 5304', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('7375f6f0-4821-5fba-b78f-43205fbd8c96', 'a57ef112-3d8d-538e-8aa2-87fa96a1219a', '{"en": "Two fingers side by side", "bn": "পাশাপাশি দুই আঙুল"}', true, 1), ('bffe8ce5-d9b3-5aad-b990-b762548c8044', 'a57ef112-3d8d-538e-8aa2-87fa96a1219a', '{"en": "Two far cities", "bn": "দূরের দুই শহর"}', false, 2), ('48b0635c-1677-5b64-bb0c-3492fad16492', 'a57ef112-3d8d-538e-8aa2-87fa96a1219a', '{"en": "A king and a servant", "bn": "রাজা ও সেবক"}', false, 3), ('c9660612-c976-573f-ac58-62a1a36149e6', 'a57ef112-3d8d-538e-8aa2-87fa96a1219a', '{"en": "Two mountains", "bn": "দুই পাহাড়"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d2dedaae-7ba5-59e7-8588-c261a40f87ab', 'd95ed6f2-5a62-5124-b067-1a379538dab6', '{"en": "Modesty (haya’) brings nothing but…?", "bn": "লজ্জাশীলতা (হায়া) কী ছাড়া কিছুই আনে না?"}', '{"en": "\"Modesty brings nothing except good.\"", "bn": "\"লজ্জা কল্যাণ ছাড়া কিছুই আনে না।\""}', 'Sahih al-Bukhari 6117', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('53bc52ff-f0e1-5c83-ab5e-db4cbbc2a63f', 'd2dedaae-7ba5-59e7-8588-c261a40f87ab', '{"en": "Good", "bn": "কল্যাণ"}', true, 1), ('0e3725cc-831a-5f4a-96ea-6fb75174d0d5', 'd2dedaae-7ba5-59e7-8588-c261a40f87ab', '{"en": "Loss", "bn": "ক্ষতি"}', false, 2), ('e52c1a3f-8960-5b65-99d4-c52417f4472b', 'd2dedaae-7ba5-59e7-8588-c261a40f87ab', '{"en": "Sadness", "bn": "দুঃখ"}', false, 3), ('8926e325-35bf-5262-a6b6-1b256dcd6853', 'd2dedaae-7ba5-59e7-8588-c261a40f87ab', '{"en": "Trouble", "bn": "ঝামেলা"}', false, 4) ON CONFLICT (id) DO NOTHING;
