INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('617a6071-9f08-5f55-b291-0878ef47419b', 'd8d9a09f-a640-5eda-9d85-d2df6172a23d', '{"en": "Who freed Jerusalem in 1187?", "bn": "১১৮৭ সালে জেরুজালেম কে মুক্ত করেন?"}', '{"en": "Salahuddin retook Jerusalem after the Battle of Hattin.", "bn": "হিত্তিনের যুদ্ধের পর সালাহউদ্দিন জেরুজালেম পুনরুদ্ধার করেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
