INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('de8a4eed-a4d9-5da6-9247-4649e951216f', 'd8d9a09f-a640-5eda-9d85-d2df6172a23d', '{"en": "Who conquered Constantinople in 1453?", "bn": "১৪৫৩ সালে কনস্টান্টিনোপল কে জয় করেন?"}', '{"en": "The Ottoman sultan Mehmed II, \"the Conqueror\".", "bn": "উসমানি সুলতান দ্বিতীয় মুহাম্মাদ, \"বিজেতা\"।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
