INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('48026ee2-6114-5f3a-98f2-6170081c076b', '6bf0ad9b-52bb-56f1-82b5-470a7624c550', '{"en": "What do we say before reading the Quran?", "bn": "কুরআন পড়ার আগে আমরা কী বলি?"}', '{"en": "\"When you recite the Quran, seek refuge in Allah from Satan, the outcast.\"", "bn": "\"যখন কুরআন পড়বে, বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাও।\""}', 'Quran 16:98', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('60e5e57d-abbf-5508-b1ec-1aacce464eca', '48026ee2-6114-5f3a-98f2-6170081c076b', '{"en": "A‘udhu billahi min ash-shaytan ir-rajim", "bn": "আউযু বিল্লাহি মিনাশ শাইতানির রাজিম"}', true, 1), ('56da5bd8-5730-5a97-9788-e33f9b01d0f8', '48026ee2-6114-5f3a-98f2-6170081c076b', '{"en": "Goodbye", "bn": "বিদায়"}', false, 2), ('5c535435-eea1-5ba2-b32a-2f7b3fb7ceee', '48026ee2-6114-5f3a-98f2-6170081c076b', '{"en": "Ameen", "bn": "আমিন"}', false, 3), ('feba2a32-a7a6-5034-8815-a8993f8e1962', '48026ee2-6114-5f3a-98f2-6170081c076b', '{"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9efb5188-861f-5841-b8e7-ed1a14218b67', '6bf0ad9b-52bb-56f1-82b5-470a7624c550', '{"en": "How many days does Ramadan have?", "bn": "রমজান কত দিনের?"}', '{"en": "A lunar month is 29 or 30 days, depending on the moon.", "bn": "চান্দ্র মাস চাঁদ অনুযায়ী ২৯ বা ৩০ দিন।"}', 'Sahih al-Bukhari 1907', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('221c18e3-45cb-5780-ae5c-988fbb9ddcb0', '9efb5188-861f-5841-b8e7-ed1a14218b67', '{"en": "29 or 30", "bn": "২৯ বা ৩০"}', true, 1), ('d4b2c6a4-9088-55b0-beb8-62d1a511e3d7', '9efb5188-861f-5841-b8e7-ed1a14218b67', '{"en": "7", "bn": "৭"}', false, 2), ('7ae7a57b-ec3a-5f68-8061-f2715fdf4e2a', '9efb5188-861f-5841-b8e7-ed1a14218b67', '{"en": "40", "bn": "৪০"}', false, 3), ('014f5d7f-e717-5c94-81de-745347cece0f', '9efb5188-861f-5841-b8e7-ed1a14218b67', '{"en": "15", "bn": "১৫"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ea3233a0-f985-5184-a139-407eccc390a3', '6bf0ad9b-52bb-56f1-82b5-470a7624c550', '{"en": "Which bird told Sulayman about the Queen of Saba?", "bn": "কোন পাখি সুলাইমানকে সাবার রানির খবর দেয়?"}', '{"en": "\"…and he inspected the birds and said: Why do I not see the hoopoe?\"", "bn": "\"…তিনি পাখিদের খোঁজ নিলেন এবং বললেন: হুদহুদকে দেখছি না কেন?\""}', 'Quran 27:20', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('8244952f-660c-5a5a-b749-06ae55bb6f35', 'ea3233a0-f985-5184-a139-407eccc390a3', '{"en": "The hoopoe (hudhud)", "bn": "হুদহুদ পাখি"}', true, 1), ('fe10d1d0-885f-564a-9d59-c2d40f1f8160', 'ea3233a0-f985-5184-a139-407eccc390a3', '{"en": "The crow", "bn": "কাক"}', false, 2), ('e2cff1c4-ef40-58b5-9333-b126e3a68337', 'ea3233a0-f985-5184-a139-407eccc390a3', '{"en": "The eagle", "bn": "ঈগল"}', false, 3), ('5afc1a34-33b0-5fff-888a-14e10ba67b83', 'ea3233a0-f985-5184-a139-407eccc390a3', '{"en": "The parrot", "bn": "টিয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('53c2c5c1-ebfe-5241-9e6e-2dc3e98ad14c', '6bf0ad9b-52bb-56f1-82b5-470a7624c550', '{"en": "What should we do when someone says As-salamu alaykum?", "bn": "কেউ আসসালামু আলাইকুম বললে আমাদের কী করা উচিত?"}', '{"en": "Replying to salam is a duty.", "bn": "সালামের জবাব দেওয়া কর্তব্য।"}', 'Quran 4:86', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('4a3eb3da-b673-5b7b-aaa2-05b916c3f9f6', '53c2c5c1-ebfe-5241-9e6e-2dc3e98ad14c', '{"en": "Reply: Wa alaykum as-salam", "bn": "জবাব দেওয়া: ওয়া আলাইকুমুস সালাম"}', true, 1), ('d0a7ab7c-9bbf-5677-b2d8-bb4994032df0', '53c2c5c1-ebfe-5241-9e6e-2dc3e98ad14c', '{"en": "Ignore them", "bn": "উপেক্ষা করা"}', false, 2), ('73e445a1-3829-5160-a32b-fd7489e2eb15', '53c2c5c1-ebfe-5241-9e6e-2dc3e98ad14c', '{"en": "Run away", "bn": "দৌড়ে পালানো"}', false, 3), ('6c6f6eb6-caa5-59c6-85ed-e72b67f3dfc1', '53c2c5c1-ebfe-5241-9e6e-2dc3e98ad14c', '{"en": "Laugh", "bn": "হাসা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quizzes (id, title, topic, difficulty, time_limit_seconds, points_per_question, review_status, sort_order) VALUES ('89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "Eid", "bn": "ঈদ"}', 'general', 'easy', NULL, 10, 'in_review', 35) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('eb0864bf-ba2b-5723-88e1-70175808ef6e', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "How many Eids do Muslims celebrate each year?", "bn": "মুসলমানরা প্রতি বছর কয়টি ঈদ উদ্‌যাপন করে?"}', '{"en": "\"Allah has replaced them with two better days: al-Adha and al-Fitr.\"", "bn": "\"আল্লাহ তোমাদের এর বদলে দুটি উত্তম দিন দিয়েছেন: আযহা ও ফিতর।\""}', 'Sunan Abi Dawud 1134', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('cc98a4ce-5dce-5927-b763-821522968b23', 'eb0864bf-ba2b-5723-88e1-70175808ef6e', '{"en": "1", "bn": "১"}', false, 1), ('ae35a3de-6df8-5801-82a2-99fe8fe9e278', 'eb0864bf-ba2b-5723-88e1-70175808ef6e', '{"en": "2", "bn": "২"}', true, 2), ('96fa3e66-b054-5a0a-b5c6-b65ab0744b58', 'eb0864bf-ba2b-5723-88e1-70175808ef6e', '{"en": "3", "bn": "৩"}', false, 3), ('35552d33-62d7-5fe8-9c53-a1ac8edc0952', 'eb0864bf-ba2b-5723-88e1-70175808ef6e', '{"en": "4", "bn": "৪"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5aef6221-3ac3-5c60-ae2e-2bff063fea49', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "Eid al-Adha is on…?", "bn": "ঈদুল আযহা কোন তারিখে?"}', '{"en": "The day after Arafah.", "bn": "আরাফার পরের দিন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f823bbf4-f230-5f74-aae3-0787292bebff', '5aef6221-3ac3-5c60-ae2e-2bff063fea49', '{"en": "10 Dhul Hijjah", "bn": "১০ জিলহজ"}', true, 1), ('b1470b04-3bfc-54c0-a1a1-f3e3e4bfccca', '5aef6221-3ac3-5c60-ae2e-2bff063fea49', '{"en": "1 Shawwal", "bn": "১ শাওয়াল"}', false, 2), ('e24f60b5-0440-5f10-8090-6237e71eb44d', '5aef6221-3ac3-5c60-ae2e-2bff063fea49', '{"en": "27 Ramadan", "bn": "২৭ রমজান"}', false, 3), ('edc6a801-eabf-5e1e-85af-37a0ab949074', '5aef6221-3ac3-5c60-ae2e-2bff063fea49', '{"en": "1 Muharram", "bn": "১ মহররম"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('4224719d-5119-56b9-a2ac-e8fb5959d03d', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "In the Eid prayer, does the khutbah come before or after the prayer?", "bn": "ঈদের নামাজে খুতবা নামাজের আগে না পরে?"}', '{"en": "The Prophet ﷺ prayed first, then gave the khutbah.", "bn": "নবী ﷺ আগে নামাজ পড়তেন, তারপর খুতবা দিতেন।"}', 'Sahih al-Bukhari 962', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('a5f79fdf-2d74-5dc0-9fd3-b3f1db9b7001', '4224719d-5119-56b9-a2ac-e8fb5959d03d', '{"en": "After", "bn": "পরে"}', true, 1), ('cfdf38d3-0de4-5942-b8cd-4d4069a7aca7', '4224719d-5119-56b9-a2ac-e8fb5959d03d', '{"en": "Before", "bn": "আগে"}', false, 2), ('b7b3452b-371f-5bc8-ba8e-117c68563386', '4224719d-5119-56b9-a2ac-e8fb5959d03d', '{"en": "There is none", "bn": "নেই"}', false, 3), ('07cb6cad-4ac7-51d5-9504-4af91d802ad2', '4224719d-5119-56b9-a2ac-e8fb5959d03d', '{"en": "Both", "bn": "দুটোই"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('a3214916-77e8-5861-8582-13c4f6a785e1', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "What is sunnah to eat before going to the Eid al-Fitr prayer?", "bn": "ঈদুল ফিতরের নামাজে যাওয়ার আগে কী খাওয়া সুন্নাত?"}', '{"en": "He ﷺ would not go out on Eid al-Fitr until he had eaten some dates, an odd number.", "bn": "ঈদুল ফিতরে তিনি ﷺ বেজোড় সংখ্যক খেজুর না খেয়ে বের হতেন না।"}', 'Sahih al-Bukhari 953', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('3de081f7-7f06-5c7e-b5f8-b945a35c43bc', 'a3214916-77e8-5861-8582-13c4f6a785e1', '{"en": "Dates, an odd number", "bn": "বেজোড় সংখ্যক খেজুর"}', true, 1), ('0c3f3002-da4e-5d14-9a3d-4aa0e7f671d7', 'a3214916-77e8-5861-8582-13c4f6a785e1', '{"en": "Nothing", "bn": "কিছু না"}', false, 2), ('e69ab314-5c69-5540-8198-71bcf27c59cb', 'a3214916-77e8-5861-8582-13c4f6a785e1', '{"en": "Meat", "bn": "গোশত"}', false, 3), ('c0137b6e-9fcc-524b-b6ac-575e7b2e9bd0', 'a3214916-77e8-5861-8582-13c4f6a785e1', '{"en": "Sweets only", "bn": "শুধু মিষ্টি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('487c16b4-65ee-5c74-93c2-493ac83a2f15', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "On Eid al-Adha, the sunnah is to eat…?", "bn": "ঈদুল আযহায় সুন্নাত হলো খাওয়া…?"}', '{"en": "He ﷺ did not eat on the day of al-Adha until he had prayed.", "bn": "আযহার দিন তিনি ﷺ নামাজ না পড়ে খেতেন না।"}', 'Jami‘ at-Tirmidhi 542', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('f54fee69-73e8-54f2-85b8-937e1c562a70', '487c16b4-65ee-5c74-93c2-493ac83a2f15', '{"en": "After the prayer", "bn": "নামাজের পরে"}', true, 1), ('f41a5235-bf25-5748-89c3-71ba0291085c', '487c16b4-65ee-5c74-93c2-493ac83a2f15', '{"en": "Before the prayer", "bn": "নামাজের আগে"}', false, 2), ('05535f54-e294-5205-a544-e2ce411d6db6', '487c16b4-65ee-5c74-93c2-493ac83a2f15', '{"en": "Only at night", "bn": "শুধু রাতে"}', false, 3), ('21d30f89-ec42-5a5a-96c5-22712bff8880', '487c16b4-65ee-5c74-93c2-493ac83a2f15', '{"en": "Nothing all day", "bn": "সারাদিন কিছু না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6e0acf7f-1dfb-57c8-a49c-fcd78112f128', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "Is fasting allowed on the two Eid days?", "bn": "দুই ঈদের দিন কি রোজা রাখা যায়?"}', '{"en": "The Prophet ﷺ forbade fasting on the day of Fitr and the day of Adha.", "bn": "নবী ﷺ ফিতর ও আযহার দিনে রোজা রাখতে নিষেধ করেছেন।"}', 'Sahih al-Bukhari 1990', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('52540600-c23b-5b99-bac1-56095dae4936', '6e0acf7f-1dfb-57c8-a49c-fcd78112f128', '{"en": "No", "bn": "না"}', true, 1), ('8294dae1-9e66-5285-a1c2-241e73f47462', '6e0acf7f-1dfb-57c8-a49c-fcd78112f128', '{"en": "Yes", "bn": "হ্যাঁ"}', false, 2), ('14c4bb9d-65ef-50c7-a503-65b9158280d8', '6e0acf7f-1dfb-57c8-a49c-fcd78112f128', '{"en": "Only half a day", "bn": "শুধু অর্ধদিন"}', false, 3), ('28738c38-96fe-58d5-a1ff-7f937fafcdf4', '6e0acf7f-1dfb-57c8-a49c-fcd78112f128', '{"en": "Only for adults", "bn": "শুধু প্রাপ্তবয়স্কদের"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9c3d7c99-237d-5b73-a2dd-5b161e05503d', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "Coming back from the Eid prayer, the sunnah is to…?", "bn": "ঈদের নামাজ থেকে ফেরার সময় সুন্নাত হলো…?"}', '{"en": "On Eid he ﷺ would go by one way and return by another.", "bn": "ঈদে তিনি ﷺ এক পথে যেতেন, অন্য পথে ফিরতেন।"}', 'Sahih al-Bukhari 986', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('91b63e35-68e0-5293-9c0b-e5dfa7c06232', '9c3d7c99-237d-5b73-a2dd-5b161e05503d', '{"en": "Take a different route", "bn": "ভিন্ন পথে ফেরা"}', true, 1), ('a6262a4d-9a12-5d8b-9340-ac0d4831c54b', '9c3d7c99-237d-5b73-a2dd-5b161e05503d', '{"en": "Run", "bn": "দৌড়ানো"}', false, 2), ('559bc15c-1d47-5127-b1f8-8b453494e540', '9c3d7c99-237d-5b73-a2dd-5b161e05503d', '{"en": "Stay silent all day", "bn": "সারাদিন চুপ থাকা"}', false, 3), ('9af85ed9-d0e7-57b9-a684-04db778b11ce', '9c3d7c99-237d-5b73-a2dd-5b161e05503d', '{"en": "Go by boat", "bn": "নৌকায় যাওয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('24ddd1ba-6f3a-5d8c-861c-ac6ceed6a427', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "When are the Eid al-Adha sacrifices made?", "bn": "ঈদুল আযহার কোরবানি কখন করা হয়?"}', '{"en": "\"Whoever slaughters before the prayer must slaughter again.\"", "bn": "\"যে নামাজের আগে জবাই করে, তাকে আবার জবাই করতে হবে।\""}', 'Sahih al-Bukhari 5545', 8) ON CONFLICT (id) DO NOTHING;
