INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('d05c85f8-a167-55c9-8bb2-ba7ebb23e327', '89fe27e9-faa0-50cd-b41e-72428da5a6f6', '{"en": "Eid al-Fitr celebrates completing…?", "bn": "ঈদুল ফিতর কী সম্পন্ন হওয়ার আনন্দ?"}', '{"en": "\"…and to complete the number (of days) and glorify Allah for guiding you.\"", "bn": "\"…যাতে তোমরা সংখ্যা পূর্ণ করো এবং তোমাদের হেদায়াতের জন্য আল্লাহর মহিমা ঘোষণা করো।\""}', 'Quran 2:185', 9) ON CONFLICT (id) DO NOTHING;
