INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ba3f52e3-7e70-596e-b46a-c04e22185eb8', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet’s whole people believed and were spared the punishment?", "bn": "কোন নবীর পুরো জাতি ঈমান এনে শাস্তি থেকে রক্ষা পায়?"}', '{"en": "\"…except the people of Yunus; when they believed, We removed from them the punishment.\"", "bn": "\"…ইউনুসের জাতি ছাড়া; যখন তারা ঈমান আনল, আমি তাদের থেকে শাস্তি সরিয়ে নিলাম।\""}', 'Quran 10:98', 1) ON CONFLICT (id) DO NOTHING;
