INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5d5d7ed8-f089-5a3f-b690-6a727775b263', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet was a carpenter?", "bn": "কোন নবী কাঠমিস্ত্রি ছিলেন?"}', '{"en": "\"Zakariyya was a carpenter.\"", "bn": "\"যাকারিয়া কাঠমিস্ত্রি ছিলেন।\""}', 'Sahih Muslim 2379', 2) ON CONFLICT (id) DO NOTHING;
