INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8e00181c-9c95-5cae-b72b-512890caf517', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet was taught to make armour?", "bn": "কোন নবীকে বর্ম বানানো শেখানো হয়েছিল?"}', '{"en": "\"And We taught him the making of coats of armour for you.\"", "bn": "\"আর আমি তাকে তোমাদের জন্য বর্ম তৈরি শিখিয়েছিলাম।\""}', 'Quran 21:80', 3) ON CONFLICT (id) DO NOTHING;
