INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ba429df9-b06c-5b8b-a729-8f3fea48fa0c', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Who made the golden calf while Musa was away?", "bn": "মুসার অনুপস্থিতিতে সোনার বাছুর কে বানিয়েছিল?"}', '{"en": "\"…and the Samiri led them astray.\"", "bn": "\"…আর সামেরি তাদের পথভ্রষ্ট করেছে।\""}', 'Quran 20:85–88', 5) ON CONFLICT (id) DO NOTHING;
