INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1dab4234-f673-5a42-b0ff-cc0497355811', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet was raised up to Allah and not crucified?", "bn": "কোন নবীকে আল্লাহ নিজের কাছে তুলে নিয়েছেন, তাঁকে ক্রুশবিদ্ধ করা হয়নি?"}', '{"en": "\"…they did not kill him, nor crucify him… rather Allah raised him to Himself.\"", "bn": "\"…তারা তাকে হত্যা করেনি, ক্রুশবিদ্ধও করেনি… বরং আল্লাহ তাকে নিজের কাছে তুলে নিয়েছেন।\""}', 'Quran 4:157–158', 6) ON CONFLICT (id) DO NOTHING;
