INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('8201a315-ef49-5e86-aee9-195e7358844c', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet was given wisdom while still a child?", "bn": "কোন নবীকে শিশু অবস্থাতেই প্রজ্ঞা দেওয়া হয়েছিল?"}', '{"en": "\"…and We gave him wisdom while still a child.\"", "bn": "\"…আর আমি তাকে শৈশবেই প্রজ্ঞা দান করেছিলাম।\""}', 'Quran 19:12', 7) ON CONFLICT (id) DO NOTHING;
