INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9abd12e0-7d7c-5d4d-beb7-b2a902aa7421', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "About which prophet does the Quran say \"We raised him to a high station\"?", "bn": "কোন নবী সম্পর্কে কুরআন বলে \"আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি\"?"}', '{"en": "\"And mention in the Book Idris… and We raised him to a high station.\"", "bn": "\"আর কিতাবে ইদরিসের কথা স্মরণ করো… আর আমি তাকে উচ্চ মর্যাদায় উন্নীত করেছি।\""}', 'Quran 19:56–57', 8) ON CONFLICT (id) DO NOTHING;
