INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('1f41575e-8be2-54ce-ab45-9ce7f895d502', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet’s son refused to board the Ark?", "bn": "কোন নবীর ছেলে নৌকায় উঠতে অস্বীকার করেছিল?"}', '{"en": "\"…I will take refuge on a mountain to protect me from the water.\"", "bn": "\"…আমি এক পাহাড়ে আশ্রয় নেব, যা আমাকে পানি থেকে রক্ষা করবে।\""}', 'Quran 11:42–43', 9) ON CONFLICT (id) DO NOTHING;
