INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('13c69707-5912-584e-9781-0fe40fca4809', 'ba8ae098-a702-5e41-a3c9-5408213576ab', '{"en": "Which prophet had the wind made subject to him?", "bn": "কোন নবীর জন্য বাতাসকে অনুগত করা হয়েছিল?"}', '{"en": "\"And to Sulayman (We subjected) the wind, blowing forcefully at his command.\"", "bn": "\"আর সুলাইমানের জন্য (অনুগত করেছিলাম) প্রবল বাতাস, যা তার আদেশে বইত।\""}', 'Quran 21:81', 10) ON CONFLICT (id) DO NOTHING;
