INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('ad9b6417-aa1b-5b8c-b2db-4209356ebf50', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "What is the twig used to clean the teeth called?", "bn": "দাঁত পরিষ্কারের ডালকে কী বলে?"}', '{"en": "\"Were it not hard on my ummah, I would have ordered them to use the siwak for every prayer.\"", "bn": "\"আমার উম্মতের জন্য কষ্টকর না হলে আমি প্রতি নামাজের জন্য মিসওয়াকের নির্দেশ দিতাম।\""}', 'Sahih al-Bukhari 887', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('dde66cb4-5809-576e-8514-50dfdb77bc0f', 'ad9b6417-aa1b-5b8c-b2db-4209356ebf50', '{"en": "Siwak (miswak)", "bn": "মিসওয়াক"}', true, 1), ('5f044771-5e50-5558-8d0c-8fe062d2dc2d', 'ad9b6417-aa1b-5b8c-b2db-4209356ebf50', '{"en": "Tasbih", "bn": "তাসবিহ"}', false, 2), ('42b696e4-7c0a-552a-95e0-c09d03910104', 'ad9b6417-aa1b-5b8c-b2db-4209356ebf50', '{"en": "Kohl", "bn": "সুরমা"}', false, 3), ('a3bb0f11-836b-5589-9712-3a519fc45157', 'ad9b6417-aa1b-5b8c-b2db-4209356ebf50', '{"en": "Henna", "bn": "মেহেদি"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('67dbe65b-7882-57fa-83d8-aafe0004c32f', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "On which side is it sunnah to lie down to sleep?", "bn": "কোন কাতে শোয়া সুন্নাত?"}', '{"en": "\"…then lie down on your right side.\"", "bn": "\"…তারপর ডান কাতে শোও।\""}', 'Sahih al-Bukhari 247', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5a287ddb-a913-5f6a-8693-252c2d1e6408', '67dbe65b-7882-57fa-83d8-aafe0004c32f', '{"en": "The right side", "bn": "ডান কাতে"}', true, 1), ('5c8b16e2-c961-56ef-8ee3-f33cf97205aa', '67dbe65b-7882-57fa-83d8-aafe0004c32f', '{"en": "The left side", "bn": "বাম কাতে"}', false, 2), ('12bc2cf4-65f9-5a95-b46e-f6b7923e6299', '67dbe65b-7882-57fa-83d8-aafe0004c32f', '{"en": "On the stomach", "bn": "উপুড় হয়ে"}', false, 3), ('45c380ea-b741-5fd3-9915-c0be2f5923f2', '67dbe65b-7882-57fa-83d8-aafe0004c32f', '{"en": "Sitting up", "bn": "বসে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('c1dcaafd-a1e4-5ab9-b394-9a9843eaf484', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "Mentioning Allah when entering home and eating keeps away…?", "bn": "ঘরে প্রবেশ ও খাওয়ার সময় আল্লাহর নাম নিলে কে দূরে থাকে?"}', '{"en": "Shaytan says: you have no place to stay and no dinner.", "bn": "শয়তান বলে: তোমাদের থাকার জায়গা নেই, রাতের খাবারও নেই।"}', 'Sahih Muslim 2018', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('20a7d326-542f-5bdc-8c29-2a86b9244fb5', 'c1dcaafd-a1e4-5ab9-b394-9a9843eaf484', '{"en": "Shaytan", "bn": "শয়তান"}', true, 1), ('62dc33c7-afeb-50d5-bd0b-528c1e8a4e5b', 'c1dcaafd-a1e4-5ab9-b394-9a9843eaf484', '{"en": "Guests", "bn": "মেহমান"}', false, 2), ('54421d0b-ddad-5506-b75a-ff1281753e0d', 'c1dcaafd-a1e4-5ab9-b394-9a9843eaf484', '{"en": "Neighbours", "bn": "প্রতিবেশী"}', false, 3), ('751e9800-f433-5783-a045-b70727dc7b1d', 'c1dcaafd-a1e4-5ab9-b394-9a9843eaf484', '{"en": "Children", "bn": "শিশুরা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5a7111a2-36a1-5ce6-9804-9f5e2c3c7abb', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "How did the Prophet ﷺ prefer to drink?", "bn": "নবী ﷺ কীভাবে পান করতে পছন্দ করতেন?"}', '{"en": "He ﷺ discouraged drinking while standing.", "bn": "তিনি ﷺ দাঁড়িয়ে পান করতে নিরুৎসাহিত করেছেন।"}', 'Sahih Muslim 2024', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('2a6aa034-16d1-5571-9347-8628d6e0cf19', '5a7111a2-36a1-5ce6-9804-9f5e2c3c7abb', '{"en": "Sitting", "bn": "বসে"}', true, 1), ('3f2653e7-8c89-5335-be1f-95d5abee46b5', '5a7111a2-36a1-5ce6-9804-9f5e2c3c7abb', '{"en": "Running", "bn": "দৌড়ে"}', false, 2), ('8aca0a12-76f1-5082-9b1d-02ca8d7ed574', '5a7111a2-36a1-5ce6-9804-9f5e2c3c7abb', '{"en": "Lying down", "bn": "শুয়ে"}', false, 3), ('741d2c8f-e0cb-5bfc-ba36-8c7b8f53e2ac', '5a7111a2-36a1-5ce6-9804-9f5e2c3c7abb', '{"en": "In one gulp", "bn": "এক চুমুকে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e19787f4-8cf5-5194-bcf8-6d1bad78b0c3', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "Visiting a sick Muslim is like being in…?", "bn": "অসুস্থ মুসলিমকে দেখতে যাওয়া যেন…?"}', '{"en": "\"…he remains in the harvest of Paradise until he returns.\"", "bn": "\"…সে ফিরে আসা পর্যন্ত জান্নাতের ফল আহরণে থাকে।\""}', 'Sahih Muslim 2568', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('c78aad29-62bc-5b43-8bb7-d27ca7030473', 'e19787f4-8cf5-5194-bcf8-6d1bad78b0c3', '{"en": "The harvest of Paradise", "bn": "জান্নাতের ফল আহরণে থাকা"}', true, 1), ('9d541c67-e493-5bdb-9b61-6c1e3ffee17c', 'e19787f4-8cf5-5194-bcf8-6d1bad78b0c3', '{"en": "A market", "bn": "বাজারে থাকা"}', false, 2), ('457855ea-da81-52e2-b4da-6c6ed0ce39d3', 'e19787f4-8cf5-5194-bcf8-6d1bad78b0c3', '{"en": "A long journey", "bn": "দীর্ঘ সফরে থাকা"}', false, 3), ('fdd85e15-75c8-52c9-82d0-304ba61685f0', 'e19787f4-8cf5-5194-bcf8-6d1bad78b0c3', '{"en": "A school", "bn": "স্কুলে থাকা"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('90c11e2c-8849-50d3-a2ac-8cf09db84449', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "Removing something harmful from the road is…?", "bn": "রাস্তা থেকে কষ্টদায়ক জিনিস সরানো হলো…?"}', '{"en": "\"…and the lowest of them is removing harm from the road.\"", "bn": "\"…আর এর সর্বনিম্ন শাখা রাস্তা থেকে কষ্টদায়ক জিনিস সরানো।\""}', 'Sahih Muslim 35', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('dd7337a1-fcc2-50da-8e37-6bfa87c86f9e', '90c11e2c-8849-50d3-a2ac-8cf09db84449', '{"en": "A branch of iman", "bn": "ঈমানের একটি শাখা"}', true, 1), ('830cc91a-5d7a-5b7f-8c2b-49b5ee3f45e3', '90c11e2c-8849-50d3-a2ac-8cf09db84449', '{"en": "Not our job", "bn": "আমাদের কাজ না"}', false, 2), ('bcd42bb4-b273-5f8f-802b-c91cd1e6371f', '90c11e2c-8849-50d3-a2ac-8cf09db84449', '{"en": "Disliked", "bn": "অপছন্দনীয়"}', false, 3), ('7e60917b-f7dd-58ba-b23d-16efd3f4aeb0', '90c11e2c-8849-50d3-a2ac-8cf09db84449', '{"en": "Only for workers", "bn": "শুধু শ্রমিকদের কাজ"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('5fff22f5-93f5-51c8-a2ed-aef74bad07cf', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "Putting on shoes, the sunnah is to start with…?", "bn": "জুতা পরার সময় কোন পা দিয়ে শুরু করা সুন্নাত?"}', '{"en": "\"…begin with the right, and when removing, begin with the left.\"", "bn": "\"…ডান দিয়ে শুরু করো, আর খোলার সময় বাম দিয়ে।\""}', 'Sahih al-Bukhari 5855', 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('88a22f81-eb71-5f60-a898-2b947b7e2195', '5fff22f5-93f5-51c8-a2ed-aef74bad07cf', '{"en": "The right foot", "bn": "ডান পা"}', true, 1), ('62865c86-8b10-5650-96b4-2344ce7b044e', '5fff22f5-93f5-51c8-a2ed-aef74bad07cf', '{"en": "The left foot", "bn": "বাম পা"}', false, 2), ('2e9ba64e-9876-5d9d-9c6c-b688e587ec14', '5fff22f5-93f5-51c8-a2ed-aef74bad07cf', '{"en": "Either", "bn": "যেকোনো"}', false, 3), ('7eae6eee-b0d1-5eb7-ab7a-0b11e34d2f1e', '5fff22f5-93f5-51c8-a2ed-aef74bad07cf', '{"en": "Both at once", "bn": "দুটো একসাথে"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('6127d0f4-cfc2-5ffe-ba9e-cd1c57bf2b6b', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "What do we say before entering the toilet?", "bn": "টয়লেটে ঢোকার আগে কী বলি?"}', '{"en": "\"O Allah, I seek refuge in You from the male and female devils.\"", "bn": "\"হে আল্লাহ, আমি পুরুষ ও নারী শয়তান থেকে আপনার আশ্রয় চাই।\""}', 'Sahih al-Bukhari 142', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b5c85fa5-46ef-5dad-b41d-b069e98abf23', '6127d0f4-cfc2-5ffe-ba9e-cd1c57bf2b6b', '{"en": "Allahumma inni a‘udhu bika minal-khubuthi wal-khaba’ith", "bn": "আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল খুবুসি ওয়াল খাবায়িস"}', true, 1), ('b92f4fc3-76a7-5dcd-8ca4-ee60a8de4fbe', '6127d0f4-cfc2-5ffe-ba9e-cd1c57bf2b6b', '{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}', false, 2), ('14244cba-d168-5f87-a278-f87231b15f54', '6127d0f4-cfc2-5ffe-ba9e-cd1c57bf2b6b', '{"en": "Ameen", "bn": "আমিন"}', false, 3), ('56c0a298-0199-5fa3-9315-0701325addd6', '6127d0f4-cfc2-5ffe-ba9e-cd1c57bf2b6b', '{"en": "Nothing", "bn": "কিছু না"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('e60cdc82-a7d3-569c-ab0e-6da9c90e4d0d', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "When yawning, we should…?", "bn": "হাই তোলার সময় আমাদের উচিত…?"}', '{"en": "\"…let him put his hand over his mouth.\"", "bn": "\"…সে যেন মুখে হাত রাখে।\""}', 'Sahih Muslim 2995', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('5d56824e-cf60-52d6-abd4-c4be57d1ce8e', 'e60cdc82-a7d3-569c-ab0e-6da9c90e4d0d', '{"en": "Cover the mouth", "bn": "মুখ ঢেকে রাখা"}', true, 1), ('d688a30f-8d4f-5826-ab58-ee8e4b899563', 'e60cdc82-a7d3-569c-ab0e-6da9c90e4d0d', '{"en": "Say Alhamdulillah", "bn": "আলহামদুলিল্লাহ বলা"}', false, 2), ('bc797c8d-549b-5597-a7a8-1f67053be635', 'e60cdc82-a7d3-569c-ab0e-6da9c90e4d0d', '{"en": "Laugh", "bn": "হাসা"}', false, 3), ('c5960c89-333c-50a2-8044-1527fe4810fc', 'e60cdc82-a7d3-569c-ab0e-6da9c90e4d0d', '{"en": "Clap", "bn": "হাততালি দেওয়া"}', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_questions (id, quiz_id, question, explanation, source_ref, sort_order) VALUES ('9545ea5b-b60c-5bb4-a825-db19a40647f9', 'e72353aa-d75d-5f49-83be-ccef2f555777', '{"en": "What is said at the start of wudu?", "bn": "অজুর শুরুতে কী বলা হয়?"}', '{"en": "Begin wudu in the name of Allah.", "bn": "আল্লাহর নামে অজু শুরু করো।"}', 'Sunan Abi Dawud 101', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_quiz_options (id, question_id, text, is_correct, sort_order) VALUES ('b69d8561-ed29-5c7b-9e6d-bea968917527', '9545ea5b-b60c-5bb4-a825-db19a40647f9', '{"en": "Bismillah", "bn": "বিসমিল্লাহ"}', true, 1), ('778cafad-2ee6-5fc5-8f7a-2dc7d9c92913', '9545ea5b-b60c-5bb4-a825-db19a40647f9', '{"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}', false, 2), ('d6bb01ee-8c7a-50de-9f8a-1fa057d67913', '9545ea5b-b60c-5bb4-a825-db19a40647f9', '{"en": "Ameen", "bn": "আমিন"}', false, 3), ('ff466fce-c7ff-539e-9c48-2e4da73ab853', '9545ea5b-b60c-5bb4-a825-db19a40647f9', '{"en": "Astaghfirullah", "bn": "আস্তাগফিরুল্লাহ"}', false, 4) ON CONFLICT (id) DO NOTHING;
